/* kalki.uz — KalkiFit «Lola» maslahatchisi matnlari (AVTO: tools/maslahat-matn-yasa.js, manba data/maslahatchi-matn.json — qo'lda tahrirlamang). uz/ru × hazil/jiddiy × kalit → variantlar */
(function (root, f) { if (typeof module === 'object' && module.exports) module.exports = f(); else root.KalkiMaslahatMatn = f(); })(typeof self !== 'undefined' ? self : this, function () { return {"uz":{"hazil":{"c_noon":["Tush bo'ldi-yu, likopcha hali bo'm-bo'sh. Ertalab biror narsa yedingizmi?","Ro'yxat bugun negadir jim. Ovqatlanib oldingizmi?","Kun yarmi o'tdi, men esa hali birorta taom ko'rmadim. Hammasi joyidami?","Choynak ham so'rayapti: bugun nonushtaga nima bo'ldi?","Tushlik payti! Ertalabdan beri biror narsa yedingizmi yoki yozishni unutdingizmi?"],"cel_day":["Qarsaklar! Kun me'yorga xuddi o'lchab qo'ygandek tushdi: {k} / {l} kkal.","Nishonga tegdi! {k} / {l} kkal — bugungi kun a'lo.","{k} / {l} kkal — xuddi soat kabi aniq. Qoyil!","Bugungi kun chiroyli yakunlandi: {k} / {l} kkal. Men juda-juda xursandman!","Mana bu aniqlik! {k} / {l} kkal. Kunni zo'r o'tkazdingiz."],"cel_p":["Ura! Bugun oqsil {p} / {g} g — maqsad bajarildi!","Oqsil cho'qqisi zabt etildi: {p} / {g} g.","{p} g oqsil! Bugungi reja bajarildi, qoyil.","Mana bu natija: {p} / {g} g oqsil. Quvonchim ichimga sig'mayapti!","Bayram! Bugun oqsil to'liq: {p} g."],"d_empty":["O'sha kun kundalik bo'sh qolgan — u ham dam olgan shekilli.","Bu kunda yozuv yo'q. Kundalik ham ba'zan ta'tilga chiqadi.","O'sha kun sahifa toza. Hechqisi yo'q, keyingi kunlar yozilsin.","Bu kun yozilmagan — sirli kun bo'lib qoldi.","O'sha kun yozuvsiz o'tgan — bunday kunlar ham bo'ladi."],"d_low":["O'sha kuni juda oz yeyilgan — yoki ba'zi ovqatlar yozilmay qolgandir.","Bu kun ancha yengil o'tgan. Hammasi yozilganmi yoki likopcha yashirinib qolganmi?","O'sha kun me'yordan ancha kam. Ovqat esdan chiqib qolmagan bo'lsa edi.","Bu kunda kaloriya kam — ehtimol, yozish esdan chiqqandir.","O'sha kuni oz yeyilgan. O'zingizga g'amxo'rlik muntazam ovqatdan boshlanadi."],"d_ok":["O'sha kun me'yorda — namunali kun!","Bu kunni ramkaga solib qo'ysa bo'ladi: me'yorda.","O'sha kuni likopcha va maqsad bir tilda gaplashgan.","Bu kun aniq nishonga tekkan — barakalla!","O'sha kun muvozanatda o'tgan. Shunday kunlar ko'proq bo'lsin!"],"d_over":["O'sha kuni me'yordan {x} kkal ko'p bo'lgan — bayramona kun bo'lgandir.","Bu kun {x} kkal ortiqcha bilan o'tgan. Bir kun hammasini hal qilmaydi.","+{x} kkal — o'sha kuni dasturxon saxiy bo'lgan. Hechqisi yo'q.","O'sha kun me'yordan {x} kkal oshgan. Hayotda bunday kunlar ham bo'ladi.","Bu kunda {x} kkal ortiq. O'tgan ish — keyingi kunlar muhimroq."],"g_day":["Kun qizib ketdi, tushlik ham navbatda turibdi!","Kuningiz xayrli! Men shu yerda, likopchangizni qo'riqlab o'tiribman.","Salom-salom! Kunning o'rtasi — choy va mazali tushlik payti.","Yana ko'rishdik! Kun yarmiga keldi, ishlar qanday ketyapti?","Kunduzgi salom! Bugungi menyuga bir ko'z tashlaymizmi?"],"g_evening":["Qani, kechki ovqat nima bo'larkin? Kun charchatdi, lekin dasturxon kutyapti.","Oshxonadan yoqimli hid kelyaptimi? Kechingiz xayrli!","Kun oxiriga yaqinlashdik — choy damlab, natijalarni ko'ramiz.","Kech kirdi, men esa hali ham sizning tarafingizdaman.","Oqshom muborak! Likopcha kunning so'nggi sahnasiga tayyorlanyapti."],"g_morning":["Uyg'ondingizmi? Choynak qaynayapti, men esa kunni sizga atab rejalashtiryapman.","Tong muborak! Nonushta bugun bosh rolda — sahnaga chiqishga tayyor.","Salom, erta turuvchi! Quyosh ham, men ham sizni kutib turgandik.","Ertalabki salom! Likopcha hozircha bo'm-bo'sh, lekin kayfiyati a'lo.","Quyosh chiqdi, men shu yerdaman. Bugun qaysi taom birinchi bo'lib kelar ekan?"],"g_night":["Tun yarmi-ku! Yostiq sizni sog'inib qoldi, menimcha.","Ertangi nonushta yaxshi uyqudan keyin yanada mazali bo'ladi. Shirin tush!","Hali uxlamadingizmi? Oy ham esnay boshladi.","Telefon ham, men ham dam olamiz — siz ham bir oz dam oling.","Tungi salom! Yulduzlar chiqdi, demak, uyqu ham yaqin."],"m_eve":["So'nggi kunlardan {n} tasida kechki ovqat bosh rolni oldi. Tushlikni to'yimliroq qilsakmi?","Kechki ovqat {n} kunda kunning yulduzi bo'ldi. Tushlikka ham biroz e'tibor beraylik.","{n} kunda kechqurun likopcha eng to'la bo'ldi. Tushlikni mo'lroq olsak, kech yengil o'tadi.","Dasturxon {n} kun kechqurun g'olib chiqdi. Tushlikka yaxshi oqsil qo'shib, hisobni tenglashtiramiz.","Tushlik to'yimli bo'lsa, kechqurun oson: {n} kunda kunning asosiy qismi kechga qolgan edi."],"m_fat_better":["Kecha yog' {x} g ortiq edi, bugun esa ancha yaxshi. Qoyil!","Yog'li kun ortda qoldi — bugun ancha yengil. Zo'r!","Tartib tiklandi: kecha yog' maqsaddan {x} g o'tgandi, bugun joyida. Yoqdi!","Kechagi shoshqaloq yog' bugun tinchlandi. Juda soz!","Asar ham qolmadi: kechagi ortiqcha {x} g yog' bugun yo'q. Mana bu qaytish!"],"m_kcal_better":["Kecha {x} kkal ortiq edi, bugun hammasi o'z izida. Zo'r!","Kechagi kun ortda — bugun me'yor joyida. Qoyil!","Hisob kecha {x} kkalga oshgandi, bugun esa tekis. Yoqdi!","Qochib ketgan muvozanat bugun qaytib keldi. Ajoyib!","Unutildi: kechagi {x} kkal tarixda qoldi, bugun hammasi rejadagidek."],"m_prot3":["{n} kundan beri oqsil sal orqada qolyapti. Nonushtaga tuxum qo'shsakmi?","Oqsil {n} kundirki, navbat kutyapti. Tushlikka tovuq yoki baliq — zo'r tanlov.","Ketma-ket {n} kun oqsil marraga yetmadi. Bugun qatiq va tuxum yordamga kelsin.","Chetda turgan oqsilni ({n} kun bo'ldi) bugun tovuq yoki baliq bilan sahnaga chiqaramiz.","Ertalab tuxum, tushlikda baliq — va {n} kunlik oqsil kamligi joyiga tushadi."],"m_pstreak":["Oqsil bilan do'stlik mustahkam: {n} kun ketma-ket maqsad bajarildi!","Seriya: {n} kun oqsil joyida! Juda zo'r.","{n} kundirki, oqsil marrada. Siz oqsil ustasisiz!","Ketma-ket {n} kun — oqsil endi haqiqiy odat bo'ldi.","A'lo baho: oqsil bo'yicha {n} kun. Oldinga!"],"m_skipbf":["So'nggi 5 kundan {n} tasida nonushta yozilmabdi. Ertalab bir piyola qatiq bilan boshlasakmi?","Nonushta {n} kun ta'tilda bo'ldi. Ertaga tuxum va non bilan qaytaramizmi?","5 kundan {n} tasida ertalab likopcha bo'sh qoldi. Yengil nonushta — chiroyli boshlanish.","Ertaga bo'tqa yoki tuxum bilan nonushtani chaqiramiz — u {n} marta darsga kelmadi.","Choy bilan bir bo'lak pishloq ham nonushta-ku! So'nggi kunlarda {n} ta nonushta tushib qoldi."],"m_streak":["{n} kun ketma-ket me'yorda! Bu allaqachon odat, oldinga!","Ketma-ketlik {n} kun! Men siz bilan faxrlanaman.","Hisob {n} kundirki joyida. Siz menga ilhom beryapsiz!","Mana bu seriya: {n} kun me'yorda. Keyingi kunni ham qo'shamizmi?","Ketma-ket, aniq, chiroyli — {n} kun. Zo'r ketyapmiz!"],"mk_c_bajarildi":["Uglevod rejani bajardi — non va yorma bugun yaxshi ishladi.","Uglevod maqsadda. Energiya ombori to'la!","Uglevodlar o'z joyini topdi. Bugungi kun muvozanatda.","Uglevod nishonga tegdi. Shu ritmda davom!","Uglevodlar bugun intizomli — aynan maqsadda."],"mk_c_deyarli":["Uglevod marraga yaqin — yana {left} g. Bir olma bu safarni yakunlaydi.","Uglevod deyarli yetib keldi. Ortiqcha non bugun dam olsin.","Uglevodga {left} g qoldi — bir hovuch meva oxirgi qadamni bosadi.","Uglevod finishni ko'ryapti. Shirinlikni ertangi kunga qoldirsak bo'ladi.","Uglevod rejasi tugashiga oz: {left} g. Qo'shimcha non endi tomoshabin."],"mk_c_kam":["Uglevod hali kam — kun davomida non, yorma yoki meva uni yetkazib keladi.","Uglevodlar hali yo'lda: {left} g joy bor. Bir meva yoki bo'tqa ularni chaqiradi.","Uglevodga bugun {left} g bo'sh o'rin. Grechka yoki olma bu o'rinni egallaydi.","Uglevod sekin kelyapti. Bir bo'lak non yoki guruch bilan tezlashtirsak bo'ladi.","Uglevod rejasida bo'sh joy ko'p. Meva, yorma, non — kun oxirigacha bemalol."],"mk_c_oshdi":["Non bugun bosh rolda — uglevod {x} g ko'p. Keyingi safar yarim bo'lak yetadi.","Uglevod {x} g ortiq. Eng oson qadam: nonni yarim bo'lakka qisqartirish.","Uglevodlar bugun {x} g ko'proq kelib qoldi. Non yarmiga tushsa, hammasi joyiga tushadi.","{x} g uglevod ortiqcha — non bilan biroz kelishib olsak bo'ladi: yarim bo'lak.","Shirinlik va non bugun faol: +{x} g uglevod. Nonni yarim qilsak, muvozanat qaytadi."],"mk_f_bajarildi":["Yog' rejasi to'ldi. Bugun yog'li taomlarga «rahmat, yetarli» deymiz.","Yog' maqsadga yetdi — qazi va chuchvara ertangi kunni kutib tursin.","Yog' bugungi ulushini oldi. Endi yengil taomlar navbati.","Yog' joyida. Yog'li taomlar uchun bugungi sahna yopildi.","Yog' maqsad atrofida — moyli bazmni bugunga shu yerda yakunlasak bo'ladi."],"mk_f_deyarli":["Yog' marraga yaqinlashdi — yana {left} g. Qo'shimcha moyni bugun dam oldiramiz.","Yog' deyarli rejada. Saryog'ga bugun ta'til berib tursak bo'ladi.","Yog'ga {left} g qoldi — bu bo'shliqni ovqat o'zi to'ldiradi, moy qo'shmasak ham.","Yog' finishga oz qoldi. Qo'shimcha qaymoq bugun tomoshabin bo'lib tursin.","Yog' joyiga yaqin: {left} g. Salatga moyni bir tomchi kamroq quysak, ajoyib."],"mk_f_kam":["Yog' hali kam — bu yaxshi xabar. Kun davomida u o'z yo'lini o'zi topadi.","Yog' bugun kamtar: yana {left} g joy bor. Ataylab qo'shmasak ham bo'ladi.","Yog' hali sahnaga chiqmadi — va bu ajoyib. Oddiy taomlar bilan o'zi yetib keladi.","Yog' uchun {left} g bo'sh joy bor. Xavotir yo'q, u doim o'zi kelib qoladi.","Yog' ozroq — tashvishlanmang. Moy va yong'oq kun davomida o'z hissasini qo'shadi."],"mk_f_oshdi":["Yog' bugun {x} g ortiqcha mehmon bo'ldi. Keyingi ovqatda tovuq, baliq yoki sabzavot.","Yog' rejadan {x} g oshdi — keyingi likopchani tovuq yoki baliqqa topshiramiz.","Moy bugun saxiy: {x} g ortiq. Endi navbat sabzavot va baliqqa.","Yog' {x} g ko'p bo'ldi. Kechki ovqat tovuq va salat bo'lsa, muvozanat qaytadi.","{x} g yog' ortiqcha — qo'rqinchli emas. Keyingi taom yog'sizroq: baliq yoki sabzavot."],"mk_p_bajarildi":["Oqsil rejani bajardi: {v}/{g} g. Endi to'qlik sizga uzoq hamroh bo'ladi.","Oqsil bugun a'lo baho oldi — {v}/{g} g. Kechgacha to'q yurasiz.","Oqsil maqsadi zabt etildi! To'qlik endi shoshilmay ketadi.","{v}/{g} g — oqsil o'z vazifasini bajardi. Ishtaha ham tinchroq bo'ladi.","Oqsil marraga yetdi. Endi u sizni uzoq vaqt to'q ushlab turadi."],"mk_p_deyarli":["Oqsil marraga yaqin: yana {left} g. Bitta tuxum bu ishni chiroyli yakunlaydi.","Oz qoldi — {left} g oqsil. Bir stakan qatiq oxirgi qadamni bosadi.","Oqsil finishni ko'rib turibdi: {left} g qoldi. Bir bo'lak pishloq yetkazib qo'yadi.","Yana {left} g — va oqsil marraga yetadi. Tvorog bilan yordam bersak bo'ladi.","Oqsil deyarli uyida: {left} g qoldi. Bir hovuch no'xat yoki tuxum — va tayyor."],"mk_p_kam":["Oqsil hali navbatda turibdi: yana {left} g. Tuxum, qatiq yoki tovuq uni tezroq chaqiradi.","Likopchada oqsil kamtar bo'lib qoldi — yana {left} g. Baliq yoki no'xat yordamga keladi.","Oqsil bugun sahnaga hali chiqmadi: {left} g qoldi. Qatiq yoki tuxum bilan taklif qilamiz.","Yana {left} g oqsil — bir bo'lak tovuq yoki bir kosa mosh buni yengil hal qiladi.","Oqsil hisobida bo'sh joy bor: {left} g. Tuxum, baliq, loviya — tanlov sizda."],"mk_p_oshdi":["Oqsil bugun ishtiyoq bilan ishladi — {x} g ortiq. Muammo emas, kaloriyaga ko'z tashlab turing.","Oqsil rejadan {x} g oshib ketdi. Zarari yo'q, kaloriya esa nazoratda tursin.","Oqsil bugun ikki smena ishladi. Odatda bu yaxshi, faqat kaloriyani kuzatib boring.","Oqsil mo'l-ko'l: maqsaddan {x} g ko'p. Xavotir yo'q, kaloriya hisobiga qarab qo'ying.","Oqsil saxiy chiqdi — {x} g ortiqcha. Zarar qilmaydi, kaloriya ham chegarada bo'lsin."],"q_full":["Qalay, oshqozon mamnunmi? To'qlikni sezyapsizmi?","Hozir o'zingizni qanday sezyapsiz: to'qmisiz?","Likopcha o'z ishini qildimi? To'qmisiz?","Savolim bor: bugungi ovqatlardan keyin to'qmisiz?","Ichki ovoz nima deyapti — to'q bo'ldingizmi?"],"q_mood":["Bugun kun qanday o'tyapti?","Kayfiyat ob-havosi qanday: quyoshlimi?","Qalay, bugungi kun sizga yoqyaptimi?","Bir savol: kayfiyatingiz bugun qanday?","Kun sizni erkalayaptimi yoki charchatyaptimi?"],"qr_full_mid":["Tushunarli. Yengil tamaddiga joy bor — {left} kkal. Qatiq yoki olma mos keladi.","O'rtachami? Unda bir piyola qatiq yoki meva — ajoyib qo'shimcha.","Bir oz joy qolibdi: {left} kkal. Meva shu yerda navbat kutyapti.","Bo'pti. Xohlasangiz, yengil narsa — qatiq yoki bir hovuch meva.","Zaxirada {left} kkal bor. Kichik tamaddi uchun qatiq juda mos."],"qr_full_no":["Tushundim! {left} kkal zaxira bor — tuxum yoki qatiq zo'r tanlov.","Ishtaha uyg'ondimi? {left} kkal bor, tovuq yoki tvorog ishni bajaradi.","Hech gap yo'q, {left} kkal sizniki. Oqsilli narsa olsak — tuxum, qatiq.","Mana yechim: {left} kkal ichida tvorog yoki qaynatilgan tuxum.","Yana yeyish mumkin — {left} kkal bor. Tovuq yoki qatiq uzoqroq to'q tutadi."],"qr_full_yes":["Zo'r! To'q bo'lsangiz, majburan yemang — likopcha kutib turadi.","Ajoyib! To'qlikni seza olish — haqiqiy super kuch.","Tushundim! Ichki ovozingizni eshitayotganingiz juda yoqdi.","Bo'ldi, qolganini keyinga saqlaymiz — ovqat qochib ketmaydi.","Mana bu ko'nikma! «Yetdi» deb to'xtash — chempionlarning ishi."],"qr_mood_bad":["Afsus... Bugun maslahatlarimni yumshoqroq qilaman. O'zingizni asrang.","Tushundim. Bugun hisob-kitob ikkinchi o'rinda, siz birinchi.","Hammada ham shunaqa kunlar bo'ladi. Men bugun jimroq va yumshoqroq bo'laman.","Quchoq yuboraman! Bugun hech qanday bosim yo'q, maslahatlar yengil bo'ladi.","Eshitdim. Bugun raqamlar dam oladi, maslahatlarim esa yumshoq bo'ladi."],"qr_mood_good":["Zo'r! Kayfiyatingiz yaxshi bo'lsa, men ham quvonaman.","Ura! Bugun kun siz tomonda ekan.","Ajoyib! Shu quyoshli kayfiyatni kechgacha saqlaymiz.","Eshitib xursand bo'ldim! Bugun hamma narsa oson ketsin.","Mana bu yangilik! Kuningiz shunday davom etsin."],"qr_mood_ok":["O'rtacha kunlar ham bo'ladi — men yoningizdaman.","Mayli, har kun bayram bo'lavermaydi. Bir piyola choy yordam beradi.","Shunaqa kunlar ham bor. Kechgacha hali yaxshi narsalar bo'lishi mumkin.","Unda bugun o'zingizga biroz mehribonroq bo'laylik.","Yomon emas-ku! Men shu yerdaman, birga davom etamiz."],"r_a":["{Src} bugun yog'ni {x} g oshirib yubordi. Kechki ovqatda tovuq yoki baliq navbatni oladi.","Yog' rejadan {x} g ilgarilab ketdi — bunga {src} sababchi. Keyingi likopchaga baliq va sabzavot taklif qilaman.","Bugun yog' juda faol: +{x} g, asosan {src}dan. Endi navbat yog'sizroq oqsilda — tovuq yoki baliqda.","{x} g ortiqcha yog' — {src} o'z hissasini qo'shdi. Keyingi taomni tovuq va sabzavot bilan yengillatamiz.","Yog' bugun bayram qildi, {x} g ko'proq. Keyingi ovqatda baliq yoki tovuq bilan sabzavot — muvozanat qaytadi."],"r_b":["Non bugun bosh rolda: uglevod {x} g ortiq, oqsil esa {p} g ortda. Keyingi sahnaga tuxum yoki qatiqni chiqaramiz.","Uglevod poygada {x} g oldinda, oqsil {p} g orqada qoldi. Unga tuxum yoki tovuq bilan yordam beraylik.","{Src} uglevodni {x} g ko'paytirdi, oqsil esa {p} g kutib turibdi. Bir bo'lak non o'rniga qatiq — adolatli almashinuv.","Xamirli taomlar bugun g'olib: +{x} g uglevod. Oqsilga hali {p} g bor — tuxum, qatiq yoki tovuq taklif qilaman.","Likopcha bir tomonga og'di: uglevod {x} g ortiq, oqsil {p} g kam. Nonni biroz kamaytirib, tuxum qo'shsak, tekislanadi."],"r_c":["Oqsil hali {p} g kutyapti. Kechki ovqatda uni tovuq yoki baliq bilan xursand qilamiz.","Kun oxiriga yaqin, oqsil esa {p} g qarzdor qolmoqchi. Kechki taomga tuxum yoki qatiq — va hisob yopiladi.","Kechki ovqat — hal qiluvchi tur: oqsilga yana {p} g. Tovuq, baliq yoki qatiq maydonga tushadi.","Oqsil hisobida {p} g bo'sh joy turibdi. Kechki likopchaga baliq yoki tovuq taklif qilaman.","Oqsil marrasiga {p} g qoldi. Bir piyola qatiq yoki bir-ikki tuxum bilan finishga yetamiz."],"r_d":["Kaloriya joyida, lekin yog' {sh} % bilan stolni egallab oldi. Ertaga oqsilga ko'proq joy beramiz — u to'qlikni uzoqroq ushlaydi.","{Src} likopchada ko'p joy oldi: kaloriyaning {sh} % i yog'dan. Keyingi ovqatda oqsil navbati — to'qlik uzoqroq.","Hisob a'lo, tarkib biroz qiyshiq: yog' {sh} %. Ertaga suzma yoki tovuq qo'shsak, to'qlik ham uzoqroq bo'ladi.","Yog' bugun ko'pchilik ovozni oldi — {sh} %. Oqsilga ham so'z beraylik: u sizni uzoqroq to'q saqlaydi.","Raqam joyida, ammo kaloriyaning {sh} % i yog'dan keldi. Ertangi nonushtaga tuxum yoki qatiq — oqsil o'z o'rnini qaytarib oladi."],"r_e":["Bugun dasturxon saxiy bo'ldi: +{x} kkal. Bir kun hech narsani buzmaydi — ertaga shirinlikni bir bo'lakka qisqartiramiz.","{Src} bugun me'yorni {x} kkal ga kengaytirdi. Xavotirga o'rin yo'q: ertaga kechki likopcha biroz kichikroq — shu yetadi.","+{x} kkal — mehmondorchilik kunlari ham bo'ladi. Ertangi reja oddiy: bitta ovqatni sabzavot bilan to'ldiramiz.","Kun to'kin o'tdi, me'yordan {x} kkal ko'p. Ertaga 15 daqiqa sayr — oyoqlar ham xursand, hisob ham.","Me'yor bugun {x} kkal ga cho'zildi, xolos. Natija bir kunda o'zgarmaydi; ertaga choyni shirinliksiz ichib ko'ramizmi?"],"r_f":["Oqsil, yog', uglevod — uchalasi kelishib oldi. Bugun likopcha a'lo baho oldi!","Bugungi taomlar maqsadga aniq tushdi. Men hatto biroz hayajondaman — ajoyib kun!","Hisob chiroyli, likopcha chiroyli, kun ham chiroyli. Shu ruhda davom etamiz!","Mana bu muvozanat! Kaloriya ham, makrolar ham o'z joyida turibdi. Sizdan faxrlanaman.","Bugun hamma ko'rsatkich bir ovozdan rozi. Bunday kunlarni ertaga ham qaytaramiz!"],"r_kam":["Bugun hozircha {k} kkal — xavfsiz chegara esa {min} kkal. Iltimos, yana bir to'yimli taom qo'shing, men sizdan xavotirdaman.","Kun oxirlab qoldi, siz esa atigi {k} kkal yedingiz ({min} kkal dan past). Bir likopcha issiq ovqat hozir juda o'rinli bo'ladi.","{k} kkal — bu bugun uchun juda oz, pastki chegara {min} kkal. Keling, kechki ovqatni to'yimli va mazali qilib olaylik.","Men sizni qo'llab-quvvatlayman, lekin {k} kkal juda kam: xavfsiz chegara {min} kkal. Yana biror to'yimli narsa yeb oling.","Hisobda hozircha {k} kkal, bu {min} kkal dan past. Ertaga kuchingiz bo'lishi uchun yana bir mazali, to'yimli taom qo'shing."],"re_fat":["Bu safar {name} ancha yog'li chiqdi — {fg} g. Keyingisini yengilroq olsak, kun muvozanatga keladi.","{name}da {fg} g yog' bor ekan. Hech gap yo'q, keyingi ovqatga sabzavot taklif qilaman.","Yog' bugun {name} bilan {fg} g ga ko'paydi. Keyingi likopchani yengilroq qilamizmi?","Mazali-ku, lekin {name}ning yog'i {fg} g. Keyingi ovqatda salat bilan muvozanat qilamiz.","Navbatni sabzavot va qatiqqa beramizmi? {name}da {fg} g yog' bor edi."],"re_first":["Kun ochildi! {name} — {k} kkal, birinchi bo'lib keldi. Yana {left} kkal bor.","Mana boshlanish! {name} ({k} kkal) bugungi ro'yxatni ochib berdi.","Birinchi qadam: {name}, {k} kkal. Kun uchun hali {left} kkal joy bor.","{name} bugun sahnaga birinchi chiqdi — {k} kkal. Olqishlar!","Yozildi! {name}, {k} kkal — kun chiroyli boshlandi, qolgani {left} kkal."],"re_goal":["{name} bilan marraga yaqinlashdik — qolgani {left} kkal. Zo'r joydamiz!","Deyarli manzildamiz: {name} qo'shildi, yana {left} kkal qoldi.","Chiroyli ketyapmiz: {name}dan keyin me'yorgacha {left} kkal.","Kun rejasi qariyb to'ldi: {name}dan keyin {left} kkal bor. Ajoyib!","Finishga oz qoldi! {name} bilan qolgani {left} kkal."],"re_light":["Atigi {k} kkal! {name} — yengil va foydali, zo'r tanlov.","Yengil-yelpi! {name}, faqat {k} kkal. Likopcha ham rahmat aytyapti.","Kunning eng yoqimli mehmoni: {name}, {k} kkal.","Vitaminlar safi kengaydi: {name}, bor-yo'g'i {k} kkal. Qoyil!","Mana bu yengillik! {name} — {k} kkal, foydasi esa katta."],"re_ok":["{name} keldi-yu, {k} kkal olib keldi. Hammasi joyida, yana {left} kkal bor.","Zo'r, {name} ({k} kkal) ro'yxatga tushdi. Zaxirada hali {left} kkal.","Likopcha mamnun: {name} — {k} kkal, qolgani {left} kkal.","Qabul qilindi: {name}, {k} kkal. Kun hali {left} kkal bilan kutyapti.","Yaxshi tanlov! {name} {k} kkal berdi, oldinda yana {left} kkal."],"re_over":["{name} bilan me'yordan {x} kkal o'tdik. Hechqisi yo'q, bir kun hech narsani buzmaydi.","Bugun {name} biroz saxiy chiqdi — {x} kkal ortiq. Ertaga yana o'z izimizga qaytamiz.","Mayli, kun bitta: {name} me'yorni {x} kkalga oshirdi, ertaga davom etamiz.","Hisob {x} kkal yuqori, {name} ham shu hisobda. Tashvishlanmang, ertaga yangi sahifa.","Bir kunlik ortiqcha hech narsani o'zgartirmaydi: {name} bilan +{x} kkal, davom!"],"re_pgoal":["Ura! {name} bilan oqsil maqsadi bajarildi — jami {p} g!","Marra! {name} oxirgi g'ishtni qo'ydi: bugun {p} g oqsil.","{name} chempionlik kamarini olib keldi — {p} g oqsil, maqsad bajarildi!","Mana bu kun! {name} bilan oqsil {p} g ga yetdi. Juda-juda xursandman!","Oqsil rejasi bajarildi! {p} g — {name} so'nggi nuqtani qo'ydi."],"re_prot":["{name} oqsil olib keldi: {pg} g! Maqsadgacha yana {pleft} g.","Oqsil safiga {name} qo'shildi — {pg} g. Qolgani {pleft} g, yetib olamiz.","Mana bu boshqa gap! {name}dan {pg} g oqsil. Yana {pleft} g qoldi.","Chempion topildi: {name}, {pg} g oqsil! Marragacha {pleft} g.","Hisobchi xursand: {name} {pg} g oqsil berdi, qolgani {pleft} g."],"rt_a":["Yog' {x} g oldinga o'tdi","Yog' bugun saxiy: +{x} g","Yog'ning ortig'i: {x} g","Yog' yugurib ketdi: +{x} g","Yog' rejadan {x} g ko'p"],"rt_b":["Non bugun bosh rolda","Xamir sahnani egalladi","Uglevod poygada birinchi","Uglevod +{x} g, oqsil ortda","Oqsil navbatda turibdi"],"rt_c":["Oqsil yana {p} g kutyapti","Kechki ovqatga {p} g oqsil","Oqsil hisobida {p} g bo'sh","{p} g oqsil navbatda","Oqsil marrasiga {p} g"],"rt_d":["Yog' {sh} % bilan yetakchi","Likopchada yog' hukmron","Yog' katta ulush oldi","Raqam joyida, tarkib og'di","Yog' sahnada: {sh} %"],"rt_e":["Dasturxon saxiy: +{x} kkal","Bugun +{x} kkal bayram","Kun to'kin o'tdi: +{x} kkal","Me'yor biroz cho'zildi","Bugun likopcha keng edi"],"rt_f":["Bugun likopcha a'lochi","Makrolar kelishib oldi","Kun besh baho bilan yopildi","Muvozanat — xuddi kitobdagidek","Hisob ham, ta'm ham joyida"],"rt_kam":["Likopcha sizni kutyapti","Bugun ovqat juda oz","Yana bir taom sig'adi","Organizm yana so'rayapti","Hozircha atigi {k} kkal"],"s_day1":["Bugun tanishuv kuni. Shunchaki yozib boring — maslahatlarni ertadan boshlayman.","Birinchi kun men faqat kuzataman va eslab qolaman. Ertaga gapirishni boshlayman.","Bugun siz yozasiz, men daftar tutaman. Maslahatlar ertadan.","Hali bir-birimizni bilib olyapmiz. Bugun yozing, ertaga birinchi maslahatim tayyor bo'ladi.","Birinchi kun hech qanday imtihonsiz o'tadi. Shunchaki yozing — ertaga suhbatlashamiz."],"s_ok":["Hozircha hammasi joyida: {k} / {l} kkal. Zaxirada yana {left} kkal bor — shoshilmasdan.","Kun silliq ketyapti: {k} / {l} kkal. Hamyonda hali {left} kkal turibdi.","{k} / {l} kkal — men xotirjamman. {left} kkal sizni kutyapti.","Hisob tinch: {k} / {l} kkal. Keyingi taomga {left} kkal joy bor.","Bugun sahnada tartib: {k} / {l} kkal, zaxira {left} kkal. Shunday davom!"],"s_wait":["Men hali tinglayapman. Yana {n} ta ovqat yozing — keyin maslahatim tayyor.","Likopcha hali bo'sh tuyulyapti. Yana {n} ta ovqat — va men gapira boshlayman.","Maslahatim dimlanyapti: yana {n} ta ovqat yozilsa, tayyor bo'ladi.","Sehrli sharim yo'q, faqat hisob bor. Yana {n} ta ovqat yozsangiz, aniq maslahat beraman.","Yana {n} ta ovqat — va kunning surati ko'rina boshlaydi. Men shu yerdaman, kutib turibman."],"t_dam":["Dam olish kunlari dasturxon bayramona — ko'proq yeyilyapti. Shanba-yakshanba uchun bitta oddiy qoida, masalan, shirinlik bir marta, yetadi.","Shanba-yakshanba likopcha ham dam oladi, lekin kattaroq bo'lib. Bitta qoida kifoya: masalan, shirinlik kuniga bir marta.","Hafta oxiri taomlar mehmonga kelganday ko'payadi. Bitta oddiy qoida o'ylab qo'ying — masalan, shirinlik bir marta.","Men sezdim: dam olish kunlari dasturxon kengayadi. Shanba-yakshanbaga bitta qoida — masalan, shirinlik bir marta — ishni hal qiladi.","Ish kunlari tartib zo'r, dam olish kunlari esa bayram. Bitta oddiy qoida kiritsak — masalan, shirinlik bir marta — bas."],"t_damOk":["Dushanba ham, yakshanba ham bir xil ritmda — dasturxon dam olish kunini ham tartibda o'tkazadi.","Hafta oxiri likopcha bayramga aylanmagan — farq kichik. Yaxshi.","Ish kuni va dam olish kuni deyarli egizak. Shunday qoladi.","Men tekshirdim: shanba-yakshanba ham tartibli o'tgan. Zo'r natija.","Dam olish kunlari ham dasturxon xotirjam — farq juda kichik."],"t_ich":["Ichimliklar jimgina katta hissa qo'shyapti. Shakarlisini suv yoki shakarsiz choyga almashtirsak, ular ham kamtar bo'ladi.","Stakandagi kaloriya ko'zga ko'rinmaydi, lekin hisobda bor. Shakarli ichimlik o'rniga suv yoki shakarsiz choy — oson almashinuv.","Ichimliklar bu davrda taomlar bilan bellashyapti. Shakarlisining o'rnini suv yoki shakarsiz choyga bersak bo'ladi.","Men sezdim: kaloriyaning bir qismi stakandan kelyapti. Shakarli ichimlikni suv yoki shakarsiz choy bilan almashtiramizmi?","Shirin ichimlik — kichik, lekin sezilarli yo'lovchi. Uni suv yoki shakarsiz choyga almashtirsak, hisob darhol yengillashadi."],"t_ichOk":["Stakan kaloriya tashimayapti — ichimliklar kam hissa qo'shgan. Zo'r.","Ichimliklar bu davrda kamtar: kaloriyasi juda oz.","Choy va suv o'z ishini qilyapti — ichimliklardan kaloriya kam.","Men tekshirdim: stakandan deyarli kaloriya kelmagan. Ajoyib tanlov.","Ichimliklar hisobda deyarli ko'rinmaydi — shunday qolsin."],"t_kechki":["Kechki ovqat bu davrda bosh qahramon — kunning 40 % dan ko'pi. Tushlikka ko'proq rol bersak, kechqurun kamroq ochiqasiz.","Kunning 40 % dan ortig'i kechqurun yeyilyapti — kechki ovqat hamma ishni o'ziga olgan. Tushlikni to'yimliroq qilsak, unga yordam bo'ladi.","Kechki dasturxon juda saxiy: kunning 40 % dan ko'pi. Tushlik biroz to'kinroq bo'lsa, kechqurun ishtaha xotirjam bo'ladi.","Men sezdim: kun asosan kechqurun qizib ketadi — 40 % dan ortig'i kechki ovqatda. To'yimli tushlik bu navbatni tenglashtiradi.","Tushlik kamtar, kechki ovqat esa bayram: kunning 40 % dan ko'pi. Tushlikni to'yimliroq qilsak, kechqurun kamroq ochiqasiz."],"t_kechkiOk":["Kechki ovqat o'z vaqtida va o'z hajmida — kun bo'ylab adolatli taqsimlangan.","Kechki dasturxon me'yorida: kun hammaga teng ulashilgan.","Kechki ovqat bu safar bosh rolni talashmadi — ulushi me'yorida. Zo'r.","Men tekshirdim: kechqurun ham, kunduzi ham joyida. Muvozanat bor.","Kechki ovqat kamtarona va to'g'ri: ulushi me'yorda. Shu ruhda davom."],"t_noMain":["Katta og'ish topilmadi — likopchangiz tartibli. Men bu safar faqat qarsak chalaman.","Qidirdim, qidirdim — katta muammo yo'q. Tartib yaxshi.","Bu davrda hech bir taom janjal qilmagan — og'ish yo'q, tartib joyida.","Tahlil zerikarli chiqdi, bu esa yaxshi belgi: katta og'ish yo'q.","Dasturxonda tinchlik: katta og'ish topilmadi. Shunday davom etamiz."],"t_oqsil":["Oqsil navbat kutib qolyapti — maqsad kam kunlarda bajarildi. Nonushtaga tuxum yoki qatiq qo'shsak, u ham erta kelib qoladi.","Oqsil bu davrda mehmon bo'lib qoldi. Nonushtada tuxum yoki qatiq — uni doimiy a'zo qilishning eng oson yo'li.","Oqsil maqsadi ko'p kunlarda yetib bormadi — yo'lda qolib ketyapti. Ertalab tuxum yoki qatiq unga yo'l ochadi.","Men sezdim: oqsil kamdan-kam maqsadga yetdi. Nonushtaga bitta tuxum yoki bir piyola qatiq — va u o'z o'rnini topadi.","Likopchada oqsil hozircha chetda turibdi — maqsad kam kunlarda bajarildi. Nonushtaga tuxum yoki qatiq qo'shamizmi?"],"t_oqsilOk":["Oqsil har kuni o'z navbatida keldi — maqsad ko'p kunlarda bajarildi. Zo'r jamoa.","Oqsil bu davrda eng intizomli ishtirokchi — ko'p kunlarda maqsadda.","Oqsil bilan do'stlik mustahkam: maqsad ko'p kunlarda bajarilgan.","Men tekshirdim: oqsil deyarli har kuni marraga yetgan. Ajoyib.","Oqsil likopchada mehmon emas, uy egasi bo'lib qoldi. Maqsad ko'p kunlarda bajarildi."],"t_top":["{f} likopchada bosh rolda. Porsiyasini biroz kichraytirsak, rol saqlanadi, natija esa tezroq keladi.","{f} — ro'yxatning yulduzi. Unga sal kichikroq sahna bersak, eng tez natija shu.","Kaloriya bo'yicha chempion: {f}. Taxtdan tushirmaymiz, faqat porsiyasini biroz qisqartiramiz.","{f} har kuni so'zni birinchi oladi. Porsiyani sal kichraytirsak, eng tez o'zgarish shundan.","Men hisobladim: eng katta ulush — {f}. Likopchani biroz kichikroq olsak, shuning o'zi tez natija beradi."],"t_wless":["Natija biroz sekin yuryapti. Odatda sababi — suv va tuz: tarozi kunlar orasida 1–2 kg tebranadi. Yoki daftarga tushmay qolgan ovqat.","Haqiqiy natija kutilgandan orqada qoldi. Ko'pincha bu suv va tuzning o'yini (kundan kunga 1–2 kg) yoki yozilmagan taom.","Tarozi hali hisobga yetib olmadi. Sababi ko'pincha suv va tuz — 1–2 kg tebranish — yoki yozilmay qolgan ovqat.","Men kutgandan sekinroq chiqdi. Odatda bunga suv va tuz sabab bo'ladi (kunlar orasida 1–2 kg) yoki bir-ikki yozilmagan ovqat.","Natija shoshilmayapti. Ko'p hollarda bu suv va tuz tebranishi — 1–2 kg atrofida — yoki daftardan qochgan taom."],"t_wmore":["Natija kutilgandan tezroq yugurdi. Ko'pincha bu suv hisobiga — keyingi haftalarda hisob bilan tenglashadi.","Tarozi biroz shoshib qoldi. Odatda sababi suv, keyingi haftalarda raqamlar tenglashadi.","Haqiqiy natija hisobdan oldinga o'tib ketdi. Ko'pincha bu suv — u keyingi haftalarda joyiga keladi.","Men kutgandan tezroq chiqdi. Bunda odatda suv ishtirok etadi; bir necha haftada hammasi tenglashadi.","Natija marraga erta yetdi. Ko'p hollarda bu suvning hissasi, keyingi haftalarda hisob bilan teng bo'ladi."],"t_wok":["Kutilgan va haqiqiy natija deyarli egizak — hisob soatday ishlayapti.","Men hisoblagan va tarozi ko'rsatgan deyarli bir xil. Yozuvlaringiz aniq.","Reja va natija qo'l berib ko'rishdi — farq deyarli yo'q.","Raqamlar bir-biriga mos: yozilganlar to'g'ri ishlayapti. Zo'r.","Kutilgan bilan haqiqiy orasida deyarli farq yo'q — demak, daftar haqiqatni aytyapti."],"t_yog":["Yog' bu davrda juda faol — ulushi 45 % dan oshdi. Tepadagi taomlardan birini haftada 1–2 marta yengilrog'iga almashtirsak, unga ham dam bo'ladi.","Likopchada yog' biroz ko'p gapiryapti: 45 % dan yuqori. Tepadagi taomlardan birini haftada 1–2 marta yengilrog'i bilan almashtiramizmi?","Yog' bu ikki hafta sahnadan tushmadi — 45 % dan ortiq. Ro'yxat boshidagi taomlardan biriga haftada 1–2 marta yengil o'rinbosar topsak bo'ladi.","Men sezdim: yog' ulushi 45 % dan oshib ketgan. Tepadagi taomlardan biri haftada 1–2 marta dam olsin, o'rniga yengilrog'i chiqsin.","Yog' juda mehmondo'st chiqdi — 45 % dan ko'p. Yuqoridagi taomlardan birini haftada 1–2 marta yengilrog'iga almashtirish yetadi."],"t_yogOk":["Yog' o'z o'rnini biladi — ulushi me'yorga yaqin. Shunday davom etamiz.","Yog' bilan kelishuv ishlayapti: me'yor atrofida, ortiqcha shovqinsiz.","Yog' bu safar kamtar chiqdi — me'yorga yaqin. Zo'r.","Men tekshirdim: yog' ulushi me'yor chizig'idan chiqmagan. Likopcha muvozanatda.","Yog' joyida, me'yor yonida turibdi. Bu bo'limda tashvish yo'q."],"t_yoz":["Bir necha kun daftarda bo'sh yoki yarim qoldi — men taxmin qilolmayman. Har kuni asosiy ovqatlarni yozsangiz, hisob aniq bo'ladi.","Ba'zi kunlar jimgina o'tib ketgan — yozilmagan yoki chala. Asosiy ovqatlar har kuni yozilsa, raqamlar haqiqatni aytadi.","Kalendarda bir nechta sirli kun bor: yozilmagan yoki chala. Har kuni hech bo'lmasa asosiy ovqatlarni yozsak, sirlar qolmaydi.","Men ba'zi kunlarni ko'rmay qoldim — ular yozilmagan yoki chala. Asosiy ovqatlarni har kuni yozib borsangiz, hisob to'g'ri chiqadi.","Bir necha kunda likopcha bo'sh ko'rinadi — aslida yozilmagan. Har kuni asosiy ovqatlarni yozsak, tahlil aniqroq bo'ladi."],"t_yozOk":["Daftar deyarli to'la — men har kunni ko'rib turibman. Zo'r.","Kunlar deyarli bo'shliqsiz yozilgan — tahlil uchun bayram.","Yozuvlar shunday to'liqki, raqamlarga ishonsa bo'ladi. Rahmat.","Men tekshirdim: deyarli hech bir kun qochib ketmagan. Ajoyib.","Kalendar deyarli to'liq — sirli kunlar yo'q."],"x_nx0":["Ertaga ham shu ritmda — formula ishlayapti","Ertaga ham xuddi shunday: jamoa o'zgarmaydi","Ertaga takror: bugungi retsept muvaffaqiyatli chiqdi","Ertaga ham shu yo'ldan — u to'g'ri yo'l","Ertaga bugungidek davom: men muxlislaringiz safidaman"],"x_nxC":["Ertaga non yarim bo'lak — ikkinchi yarmi zaxirada","Ertaga nonga yarim rol beramiz","Ertaga non bilan kelishuv: yarim bo'lak","Ertaga non kamtar bo'lsin: yarim bo'lak","Ertaga non ozroq gapirsin: yarim bo'lak"],"x_nxF":["Ertaga tushlikda tovuq yoki baliq bosh rolda","Ertangi tushlik — tovuq yoki baliqning navbati","Ertaga tushlikka baliq yoki tovuqni taklif qilamiz","Ertaga tushlik yengil: tovuq yoki baliq sahnada","Ertaga tushlik menyusiga tovuq yoki baliqni yozib qo'ying"],"x_nxK":["Ertaga kechki ovqat kichikroq likopchada — ko'z ham aldanadi","Ertaga kechqurun likopcha kichrayadi, ta'm emas","Ertaga kechki ovqatga kichik likopcha navbatchi","Ertaga kechki ovqat ixcham formatda","Ertaga kechqurun kichik likopcha katta ish qiladi"],"x_nxLow":["Ertaga 3 mahal to'yimli ovqat — nonushtadan boshlab","Ertaga nonushtani o'tkazib yubormang, keyin tushlik va kechki ovqat","Ertaga o'zingizni 3 mahal mazali ovqat bilan siylang","Ertaga nonushta, tushlik, kechki ovqat — uchalasi ham sizni kutadi","Ertaga kunni to'yimli nonushtadan boshlaylik"],"x_nxP":["Ertaga nonushtaga tuxum yoki qatiq taklif qilinadi","Ertangi nonushta yulduzlari: tuxum va qatiq","Ertaga nonushtada tuxum yoki qatiq sizni kutadi","Ertaga tongni tuxum yoki qatiq bilan boshlaymiz","Ertaga nonushtaga oqsil chaqiramiz: tuxum yoki qatiq"],"x_off0":["Og'ish yo'q — kun chiziqdan chiqmadi","Hech narsa yo'ldan adashmadi — hammasi maqsad atrofida","Bugun likopcha va maqsad do'st bo'ldi","Kamchilik qidirdim — topolmadim","Hamma ko'rsatkich o'z joyida o'tirdi"],"x_offC":["Non bugun bosh rolda: +{x} g uglevod ({src})","Uglevod {x} g ko'p — sahna {src}niki bo'ldi","Uglevodlar {x} g ortiqcha mehmon — {src}dan","Shirin va unli taomlar faol: +{x} g uglevod","Uglevod rejadan {x} g oshib ketdi"],"x_offF":["Yog' {x} g ortiqcha mehmon — {src}dan","Yog' bugun saxiy chiqdi: +{x} g ({src})","Yog' rejadan {x} g oshdi — bosh qahramon: {src}","Moy bugun ko'p gapirdi: +{x} g yog'","Yog' {x} g ko'proq kelib qoldi"],"x_offK":["Kaloriya {x} kkal chiziqdan chiqdi — {src}dan","Me'yordan {x} kkal ortiq — bugungi yulduz: {src}","Kaloriya bugun {x} kkal ko'proq sayr qildi","Kun biroz to'yimli chiqdi: +{x} kkal ({src})","Kaloriya chegaradan {x} kkal o'tib ketdi"],"x_offLow":["Bugun juda oz yedingiz: {k} kkal (xavfsiz chegara {min}). Sizni o'ylab qoldim","Bugun atigi {k} kkal — bu {min} dan kam. O'zingizni asrang","{k} kkal — xavfsiz chegara {min} dan past. Ertaga o'zingizni yaxshi ovqat bilan siylang","Kun juda yengil o'tdi: {k} kkal, chegara esa {min}. Bunisi meni xavotirga soldi","Atigi {k} kkal yeyildi (kamida {min} bo'lsin). Keling, o'zingizga g'amxo'rlik qilaylik"],"x_offP":["Oqsil {x} g navbatda qolib ketdi","Oqsilga {x} g yetmadi — u bugun kamtar edi","Oqsil marraga {x} g yetmay to'xtadi","Oqsil rejasida {x} g bo'sh joy qoldi","Oqsil bugun ozroq keldi: {x} g kam"],"x_okK":["Kaloriya chiziqdan chiqmadi: {v} / {g} kkal","Kaloriya bugun intizomli: {v} / {g} kkal","Kaloriya nishonga tegdi: {v} / {g} kkal","{v} / {g} kkal — kun muvozanatda o'tdi","Kaloriya o'z chegarasini hurmat qildi: {v} / {g} kkal"],"x_okN":["Kundalik to'la: {n} ta ovqat yozildi — hisob tiniq","{n} ta ovqat qayd etildi — hech biri yashirinmadi","Likopchalar ro'yxatda: {n} ta — hisob aniq","{n} ta ovqat yozildi — men hammasini ko'rib turibman","Har tishlam hisobda: {n} ta ovqat"],"x_okP":["Oqsil a'lo baho oldi: {v} / {g} g","Oqsil rejani uddaladi: {v} / {g} g","Oqsil bugun qahramon: {v} / {g} g","Oqsil marrada: {v} / {g} g — barakalla","{v} / {g} g oqsil — to'qlik sizning tomonda"],"x_okS":["Oyoqlar bugun ishladi: {v} qadam","Qadamlar hisobida: {v} — zo'r yurish","{v} qadam — krossovkalar mamnun","Bugun yo'lni yaxshi bosib o'tdingiz: {v} qadam","Qadamlar kuni bo'ldi: {v}"],"x_okW":["Suv rejasi to'ldi: {v} ml","Bugun suv bilan do'st bo'ldingiz: {v} ml","Stakanlar ishladi: {v} ml suv","Suv maqsadi qo'lga kiritildi: {v} ml","{v} ml suv — kun tetik o'tdi"]},"jiddiy":{"c_noon":["Tush bo'ldi, bugun hali hech narsa yozilmagan. Nonushta qildingizmi?","Salom! Bugun hali ovqat yozilmadi. Hammasi yaxshimi?","Kun yarmi o'tdi. Yegan narsangizni yozib qo'ysangiz, hisobni yuritaman.","Bugun nima yedingiz? Ro'yxat hali bo'sh.","Tushlik vaqti. Ertalab biror narsa yegan bo'lsangiz, qo'shib qo'yamizmi?"],"cel_day":["Kun me'yorga aniq tushdi: {k} / {l} kkal. Chin dildan tabriklayman.","Bugun {k} / {l} kkal — ideal natija.","Kunlik me'yor aniq bajarildi: {k} / {l} kkal. Ofarin.","Bugungi kun rejadagidek yakunlandi: {k} / {l} kkal. Tabriklayman.","Juda yaxshi kun: {k} / {l} kkal, me'yorga to'liq mos."],"cel_p":["Bugungi oqsil maqsadi bajarildi: {p} / {g} g. Juda yaxshi.","Oqsil maqsadiga yetdingiz — {p} / {g} g. Tabriklayman.","{p} g oqsil — bugungi reja bajarildi.","Bugun oqsil yetarli: {p} / {g} g. Ofarin.","Maqsad bajarildi: {p} g oqsil. Chin dildan xursandman."],"d_empty":["O'sha kuni hech narsa yozilmagan.","Bu kun uchun yozuv yo'q — hisoblab bo'lmaydi.","O'sha kun ma'lumot kiritilmagan — tahlil uchun yozuvlar yo'q.","Bu kunda ovqat qayd etilmagan.","O'sha kun bo'sh — ovqatlar kiritilmagan."],"d_low":["O'sha kuni me'yordan ancha kam yeyilgan. Ehtimol, hammasi yozilmagan.","Bu kun kaloriya juda past bo'lgan. Muntazam ovqatlanish muhim.","Iste'mol me'yordan sezilarli kam. Balki ba'zi ovqatlar yozilmay qolgandir.","O'sha kun juda kam kaloriya. Bunday kunlar ko'p bo'lmagani yaxshi.","Bu kunda me'yordan ancha kam. Barcha ovqat kiritilganmi, tekshirib ko'ring."],"d_ok":["O'sha kun me'yorda o'tgan — yaxshi natija.","Bu kunda kaloriya me'yor doirasida. Barakalla.","Me'yorga rioya qilingan kun. Shu tartib natija beradi.","O'sha kun maqsadga mos. Yaxshi ish.","Bu kun muvozanatli o'tgan — shunday davom eting."],"d_over":["O'sha kuni me'yordan {x} kkal ko'p bo'lgan. Bitta kun umumiy natijani o'zgartirmaydi.","Bu kun {x} kkal ortiqcha. Haftalik o'rtacha ko'rsatkich muhimroq.","Me'yordan {x} kkal yuqori bo'lgan. Keyingi kunlar muvozanatni tiklaydi.","O'sha kun +{x} kkal. Xotirjam davom etsak bo'ladi.","Bu kunda kaloriya {x} kkal oshgan — tashvishga o'rin yo'q."],"g_day":["Kuningiz xayrli o'tsin. Tushlikni yozib borsangiz, hisobni aniq yuritaman.","Kun yarmi — suv ichishni unutmang.","Xayrli kun. Bugungi ovqatlarni kuzatib turibman.","Salom. Tushlik vaqti yaqin — to'yimli va muvozanatli bo'lsin.","Ishlaringiz yaxshi ketyaptimi? Men yoningizdaman."],"g_evening":["Xayrli kech. Kechki ovqatni yozsangiz, kun xulosasini tayyorlayman.","Kechingiz xayrli bo'lsin. Kun qanday o'tdi?","Kechqurun yengilroq ovqat uyquni yaxshilaydi.","Bugungi kunni birga yakunlaymiz.","Kech kirdi. Kunning natijalari tayyor bo'lib qoldi."],"g_morning":["Xayrli tong. Kunni bir stakan suv va yengil nonushta bilan boshlash yaxshi.","Bugun ham birga kuzatib boramiz — tongingiz xayrli o'tsin.","Tongingiz xayrli bo'lsin. Nonushtani yozib qo'ysangiz, kun rejasini tuzaman.","Yangi kun — yangi imkoniyat.","Salom. Men shu yerdaman, savol bo'lsa yordam beraman."],"g_night":["Kech bo'ldi. Yaxshi uyqu ham ovqatlanish kabi muhim — dam oling.","Xayrli tun. Ertaga yana birga davom etamiz.","Tun yarmi yaqin. Uyqu kunning eng foydali qismlaridan biri.","Hali uyg'oqmisiz? O'zingizga dam bering, ertaga yangi kun.","Xotirjam tun tilayman. Kunni yakunlash vaqti keldi."],"m_eve":["So'nggi kunlardan {n} tasida kechki ovqat eng katta bo'ldi. Tushlikni to'yimliroq qilsak yaxshi.","{n} kunda kunning asosiy qismi kechqurunga to'g'ri keldi. Tushlikka ko'proq e'tibor beraylik.","Kechki ovqat {n} kunda kunlik hisobning eng katta qismi bo'ldi. To'yimli tushlik buni tenglashtiradi.","Tushlikda oqsil va sabzavotni ko'paytirishni taklif qilaman: so'nggi {n} kunda kechqurun ko'proq yeyildi.","Ustunlik {n} kun kechki ovqatda bo'ldi. Kun o'rtasida to'yimli ovqat kechni yengillashtiradi."],"m_fat_better":["Kecha yog' maqsaddan {x} g ko'p edi, bugun ancha yaxshi. Ofarin.","Bugun yog' miqdori me'yorga yaqin. Kechagiga qaraganda yaxshi natija.","Kechagi {x} g ortiqcha yog'dan keyin bugun muvozanat tiklandi.","Yog' bo'yicha bugun ancha yaxshi — kecha {x} g ko'p edi.","Yaxshi o'zgarish: bugun yog' nazoratda. Shunday davom etamiz."],"m_kcal_better":["Kecha me'yordan {x} kkal ko'p edi, bugun hammasi o'z izida.","Bugun me'yor joyida. Kechagi {x} kkal ortiqchadan keyin bu yaxshi natija.","Muvozanat tiklandi: kecha {x} kkal ortiq edi, bugun me'yordasiz.","Bugungi hisob rejaga mos. Kechagi kunni ortda qoldirdik.","Yaxshi qaytish — bugun me'yor ichidasiz."],"m_prot3":["{n} kundan beri oqsil maqsadga yetmayapti. Bugun nonushtaga tuxum yoki qatiq qo'shsak yaxshi.","Oqsil {n} kun ketma-ket kam bo'ldi. Tushlikka tovuq yoki baliq yaxshi tanlov.","So'nggi {n} kunda oqsil yetishmadi. Ertalab tuxum, tushlikda tovuq yordam beradi.","Qatiq va baliq yordam beradi: {n} kundirki, oqsil maqsadi bajarilmayapti.","Bugun har ovqatga bir oqsil manbaini qo'shaylik — {n} kundan beri oqsil kam."],"m_pstreak":["{n} kun ketma-ket oqsil maqsadi bajarildi. Ajoyib natija.","Oqsil maqsadi {n} kundan beri bajarilyapti. Ofarin.","Ketma-ket {n} kun oqsil yetarli. Bu juda yaxshi odat.","Davom etamiz: {n} kundirki, oqsil me'yorda.","Siz {n} kun davomida oqsil maqsadini saqladingiz. Tabriklayman."],"m_skipbf":["So'nggi 5 kundan {n} tasida nonushta yozilmagan. Ertalab yengil nonushta kunni yaxshi boshlaydi.","{n} kun nonushtasiz o'tdi. Tuxum yoki bo'tqa — tez va to'yimli variant.","Nonushta so'nggi kunlarda {n} marta tushib qoldi. Ertaga qatiq bilan boshlab ko'ramizmi?","5 kundan {n} tasida ertalabki ovqat yo'q. Kichik nonushta ham kun davomida yordam beradi.","Ertalabki ovqat {n} kunda yozilmagan. Ertaga yengil nonushta taklif qilaman."],"m_streak":["{n} kun ketma-ket me'yordasiz. Juda yaxshi natija, davom etamiz.","Ketma-ket {n} kun me'yorda — bu barqaror odat.","Hisob {n} kundirki rejaga mos. Ofarin.","Siz {n} kundan beri me'yorni saqlayapsiz. Bu katta yutuq.","Barqaror natija: {n} kun. Shunday davom eting."],"mk_c_bajarildi":["Uglevod maqsadda — yaxshi.","Uglevod maqsadiga yetdingiz. Bu kun davomida energiyani bir tekis ushlaydi.","Uglevod me'yorida. Qolgan ovqatlarda oqsil va sabzavotga e'tibor bersak yaxshi.","Kunlik uglevod maqsadi bajarildi.","Uglevod yetarli. Shu tartibni saqlasak bo'ladi."],"mk_c_deyarli":["Uglevod maqsadga yaqin: yana {left} g.","Uglevod deyarli maqsadda. Qolgan ovqatlarda nonni ko'paytirmaslik ma'qul.","Uglevod maqsadigacha {left} g qoldi — bitta meva yetarli.","Uglevod maqsadga yaqinlashdi. Shirinlik va qo'shimcha nonsiz davom etsak yaxshi.","Uglevod bo'yicha {left} g qoldi. Bu farqni sabzavot yoki meva yopadi."],"mk_c_kam":["Uglevod hali kam — kun davomida non, yorma yoki meva bilan to'ladi.","Uglevod maqsadigacha {left} g. Keyingi ovqatga yorma yoki meva qo'shsak bo'ladi.","Uglevod hozircha past. Butun donli non yoki grechka yaxshi manba.","Yana {left} g uglevod uchun joy bor — mevalar va bo'tqalar bunga mos.","Uglevod kam iste'mol qilindi. Kunning qolgan qismida yorma va mevaga e'tibor bering."],"mk_c_oshdi":["Uglevod {x} g ko'p. Nonni yarim bo'lakka qisqartirish — eng oson qadam.","Uglevod maqsaddan {x} g yuqori. Keyingi ovqatda non va shirinlikni kamaytiring.","{x} g ortiqcha uglevod. Garnirni sabzavotga almashtirsak yaxshi.","Uglevod bo'yicha {x} g ortiqcha — yarim bo'lak non kamroq ham sezilarli farq beradi.","Uglevod {x} g ga oshdi. Shirin ichimlik va qo'shimcha nonni kamaytirsak bo'ladi."],"mk_f_bajarildi":["Yog' maqsad atrofida. Bugun yog'li taomlarni shu yerda to'xtatsak yaxshi.","Yog' maqsadiga yetdingiz. Qolgan ovqatlarni yog'sizroq tanlang.","Yog' me'yorda. Endi sabzavot, tovuq yoki baliq yaxshi tanlov.","Kunlik yog' maqsadi bajarildi — yog'li qo'shimchalarsiz davom etsak bo'ladi.","Yog' yetarli. Kunning qolgan qismida yengilroq taomlarga o'tamiz."],"mk_f_deyarli":["Yog' maqsadga yaqin: yana {left} g. Qo'shimcha yog' qo'shishga hojat yo'q.","Yog' deyarli maqsadda. Bugungi qolgan ovqatlarni yog'sizroq tanlasak yaxshi.","Yog' maqsadigacha {left} g qoldi — odatiy taom buni o'zi yopadi.","Yog' maqsadga yaqinlashdi. Moy va qaymoqni bugun qo'shmaslik ma'qul.","Yog' maqsadidan {left} g kam. Qolganini ovqat o'zi beradi, alohida qo'shmang."],"mk_f_kam":["Yog' hali kam — bu yaxshi. Kun davomida odatiy ovqat bilan to'ladi.","Yog' maqsadigacha {left} g bor. Maxsus qo'shishga hojat yo'q.","Yog' hozircha kam. Qolganini kunning keyingi ovqatlari o'zi to'ldiradi.","Yog' bo'yicha {left} g zaxira bor — bu odatiy holat, alohida yog' qo'shmang.","Yog' iste'moli past. Odatiy taomlar kun oxirigacha uni to'ldiradi."],"mk_f_oshdi":["Yog' maqsaddan {x} g ko'p. Keyingi ovqatda yog'sizroq tanlang: tovuq, baliq, sabzavot.","Yog' {x} g oshdi. Keyingi taomga qovurilgan emas, qaynatilgan tovuq yoki baliq mos.","{x} g ortiqcha yog'. Keyingi ovqatni sabzavot va yog'siz oqsil bilan muvozanatlang.","Yog' me'yordan {x} g yuqori — keyingi ovqatda baliq yoki tovuq ko'kragi yaxshi tanlov.","Yog' bo'yicha {x} g ortiqcha. Qolgan ovqatlarda moy va qaymoqni kamaytirsak bo'ladi."],"mk_p_bajarildi":["Oqsil maqsadi bajarildi: {v}/{g} g. To'qlik uzoqroq saqlanadi.","Oqsil yetarli — {v}/{g} g. Bu ishtahani bir tekis ushlashga yordam beradi.","Oqsil bo'yicha maqsadga yetdingiz. Keyingi ovqatgacha to'qlik saqlanadi.","{v}/{g} g oqsil — maqsad bajarildi. Shu tartibni davom ettirsak yaxshi.","Oqsil maqsadda. Bunday kunlarda ortiqcha yegingiz kelishi kamroq bo'ladi."],"mk_p_deyarli":["Oqsil maqsadiga oz qoldi: yana {left} g. Bitta tuxum yoki qatiq yetarli.","Deyarli yetdingiz — yana {left} g oqsil. Bir stakan qatiq bilan to'ldirish mumkin.","Oqsil maqsadigacha {left} g. Kechki ovqatga bir bo'lak tovuq yoki baliq qo'shsak bo'ladi.","Yana {left} g oqsil qoldi — tvorog yoki pishloq bu farqni yopadi.","Oqsil maqsadga yaqin: {left} g yetishmayapti. Tuxum yoki qatiq yaxshi tanlov."],"mk_p_kam":["Oqsil hali kam: yana {left} g. Tuxum, qatiq, tovuq yoki baliq yaxshi manba.","Kunlik oqsilga {left} g yetmayapti — keyingi ovqatga tovuq, baliq yoki dukkakli qo'shing.","Yana {left} g oqsil qoldi. Eng qulay manbalar: tuxum, qatiq, tvorog, mosh, loviya.","Oqsil maqsadidan {left} g kam. Keyingi ovqatda tovuq yoki baliqni tanlasak bo'ladi.","Oqsilni to'ldirishga {left} g qoldi — bir stakan qatiq va tuxum yaxshi boshlanish."],"mk_p_oshdi":["Oqsil maqsaddan {x} g ko'p. Odatda bu muammo emas, lekin umumiy kaloriyani kuzating.","Oqsil yetarlidan ortiq. Zarari kam, faqat kaloriya chegarasiga e'tibor bering.","Oqsil {x} g ortiq — bu odatda xavfsiz. Kunlik kaloriyani ham hisobga olsak yaxshi.","Oqsil ko'p bo'ldi. To'qlik uchun yaxshi, ammo kaloriya me'yoridan chiqmaslik muhim.","Maqsaddan {x} g ko'p oqsil — tashvishga o'rin yo'q. Kaloriya balansini kuzatib boring."],"q_full":["Bugungi ovqatlardan keyin o'zingizni to'q his qilyapsizmi?","Hozir to'qlikni qanday sezyapsiz?","Bugun yeganlaringiz yetarli bo'ldimi?","To'qmisiz yoki yana biror narsa yegingiz kelyaptimi?","Qisqa savol: hozir to'qmisiz?"],"q_mood":["Bugun kayfiyatingiz qanday?","Kuningiz qanday o'tyapti?","O'zingizni bugun qanday his qilyapsiz?","Bugungi kun siz uchun qanday bo'lyapti?","Qisqa savol: bugun kayfiyat qalay?"],"qr_full_mid":["Yengil tamaddi uchun {left} kkal joy bor — qatiq yoki meva yaxshi.","Xohlasangiz, kichik tamaddi: bir piyola qatiq yoki olma.","{left} kkal zaxira bor: meva yoki qatiq — yengil va to'yimli tanlov.","Biroz qo'shmoqchi bo'lsangiz, qatiq yoki nok mos keladi.","O'rtacha bo'lsa, yengil narsa olsangiz bo'ladi — {left} kkal ichida."],"qr_full_no":["Sizda {left} kkal zaxira bor — tuxum yoki qatiq yaxshi tanlov.","{left} kkal bor. Oqsilli tamaddi — tvorog yoki tovuq — uzoq to'q tutadi.","Yana yeyishingiz mumkin: {left} kkal. Qaynatilgan tuxum yoki qatiq taklif qilaman.","Zaxira {left} kkal. Tovuq yoki tvorog to'yimli va yengil.","Mayli, {left} kkal ichida oqsilli narsa olaylik: tuxum, qatiq yoki tvorog."],"qr_full_yes":["To'q bo'lsangiz, shu yerda to'xtash — to'g'ri qaror.","To'qlikni sezish — juda muhim ko'nikma.","Ichki signallarga quloq solish — eng yaxshi yo'l.","Vaqtida to'xtashni bilish — sog'lom ovqatlanishning asosi.","Keyingi ovqatgacha bemalol kutishingiz mumkin."],"qr_mood_bad":["Tushunaman. Bugun maslahatlarim yumshoqroq bo'ladi. O'zingizga ehtiyot bo'ling.","Afsusdaman. Bugun raqamlar muhim emas — siz muhimsiz.","Bunday kunlar ham bo'ladi. Bugun hech qanday bosim yo'q, men yumshoqroq bo'laman.","Rahmat, aytdingiz. Bugun maslahatlar yengil bo'ladi, dam olishga harakat qiling.","Men yoningizdaman. Bugun ovqat haqida qayg'urmang, maslahatlarim yumshoq bo'ladi."],"qr_mood_good":["Eshitib xursandman. Kuningiz shu zaylda o'tsin.","Yaxshi kayfiyat — yaxshi kun demak.","Juda yaxshi. Bunday kunlar ko'p bo'lsin.","Quvondim. Siz uchun xursandman.","Shu ruh bilan davom etamiz."],"qr_mood_ok":["Tushunaman. Har kun bir xil bo'lmaydi, men yoningizdaman.","Rahmat, aytganingiz uchun. Bugun o'zingizga e'tiborliroq bo'ling.","Kechgacha hammasi yaxshilanishi mumkin.","Kichik sayr yoki choy kayfiyatni ko'tarishi mumkin.","Men shu yerdaman, qachon xohlasangiz gaplashamiz."],"r_a":["Yog' bugun maqsaddan {x} g ko'p, asosan {src}dan. Keyingi ovqatga tovuq, baliq yoki sabzavot yaxshi tanlov.","Bugungi yog' me'yordan {x} g yuqori. Asosiy manba — {src}. Keyingi taomda yog'sizroq oqsil olsak, kun tenglashadi.","Yog' bo'yicha {x} g ortiqcha. Keyingi ovqatda qovurilgan taom o'rniga qaynatilgan tovuq yoki baliqni tavsiya qilaman.","Hozircha yog' {x} g oshdi, ko'p qismi {src}dan keldi. Kechki ovqatni baliq yoki tovuq va sabzavot bilan yengil qilsak bo'ladi.","Ortiqcha {x} g yog' — tuzatsa bo'ladigan holat. Keyingi ovqatga yog'siz go'sht, baliq va ko'proq sabzavot qo'shing."],"r_b":["Uglevod maqsaddan {x} g ko'p, oqsilga hali {p} g bor. Keyingi taomda nonni kamaytirib, tuxum yoki qatiq qo'shing.","Bugun uglevod {x} g ortiq, oqsil esa {p} g yetmayapti. Tovuq, tuxum yoki qatiq ikkalasini ham tenglashtiradi.","Uglevodning ko'p qismi {src}dan: {x} g ortiqcha. Oqsilga {p} g qoldi — keyingi ovqatda tuxum yoki tovuq yaxshi tanlov.","Uglevod me'yordan {x} g yuqori, oqsil {p} g past. Keyingi ovqatda non o'rniga tovuq yoki qatiq olishni tavsiya qilaman.","Hozircha uglevod {x} g oshgan, oqsil {p} g kam. Nonning bir qismini tuxum yoki qatiqqa almashtirsak, to'qlik uzoqroq bo'ladi."],"r_c":["Bugun oqsil {p} g yetmayapti. Kechki ovqatga tovuq, baliq yoki qatiq qo'shsak, maqsadga yetamiz.","Oqsil maqsadiga {p} g qoldi. Kechki taom buning uchun eng qulay payt: tuxum yoki baliq yaxshi tanlov.","Kechqurun oqsilga hali {p} g bor. Tovuq yoki baliqning bir porsiyasi bu farqni yopishga yordam beradi.","Oqsil maqsadiga yetish uchun yana {p} g. Kechki ovqatda go'sht, tuxum yoki qatiqni asosiy qilib oling.","Hozircha oqsil {p} g kam. Kechki ovqatga oqsilli taom tanlasangiz, ertalabgacha to'q yurasiz."],"r_d":["Kaloriya me'yorda, ammo {sh} % i yog'dan, asosan {src}dan. Oqsil ko'proq bo'lsa, uzoqroq to'q yurasiz.","Bugungi kaloriyaning {sh} % i yog'dan keldi. Keyingi ovqatda yog'sizroq oqsil tanlasangiz, nisbat tenglashadi.","Umumiy kaloriya to'g'ri, lekin yog' ulushi {sh} %. Ertaga tovuq, baliq yoki tuxumni ko'proq oling — to'qlik uzoqroq saqlanadi.","Yog' kaloriyaning {sh} % ini tashkil qildi. Oqsil va sabzavotni ko'paytirsak, kun muvozanatliroq bo'ladi.","Kaloriya joyida, tarkib esa yog' tomonga og'gan — {sh} %. Keyingi taomda oqsilli mahsulotga urg'u bering."],"r_e":["Bugun me'yordan {x} kkal ko'p bo'ldi — bir kunlik holat, xavotir yo'q. Ertaga kechki ovqatni biroz kichikroq olsangiz bas.","Me'yordan {x} kkal oshdi, asosan {src}dan. Bir kun natijani buzmaydi; ertaga non porsiyasini kamaytirib ko'ring.","{x} kkal ortiqcha — bu odatiy holat. Ertaga 15 daqiqa piyoda yurish yaxshi kichik qadam bo'ladi.","Bugun kunlik me'yor {x} kkal ga oshdi. Muhimi — haftalik yo'nalish; ertaga bitta ovqatni sabzavotga boyroq qiling.","Me'yordan {x} kkal yuqori, lekin bu bir kun. Ertaga shirin ichimlik o'rniga suv yoki choy tanlasangiz kifoya."],"r_f":["Bugun kaloriya ham, oqsil, yog' va uglevod ham joyida. Juda yaxshi natija.","Muvozanatli kun: barcha ko'rsatkich maqsad atrofida. Shu tartibni ertaga ham davom ettiramiz.","Kaloriya va makrolar maqsadga mos. Bunday kunlar natijani mustahkamlaydi — rostdan quvondim.","Kun to'g'ri tuzilgan: yetarli oqsil, me'yordagi yog' va uglevod. Siz ajoyib ish qildingiz.","Hamma ko'rsatkich joyida. Bugungi tanlovlaringiz aniq va o'ylangan — shunday davom eting."],"r_kam":["Bugun hozircha {k} kkal — bu xavfsiz chegaradan ({min} kkal) past. Juda kam yeyish sog'liqqa zarar; yana bir to'yimli taom qo'shing.","Bugungi jami {k} kkal, pastki xavfsiz chegara esa {min} kkal. Kechki ovqatni to'liq va to'yimli qilishingizni so'rayman.","{k} kkal xavfsiz minimumdan ({min} kkal) kam. Organizmga yetarli quvvat zarur — iltimos, yana bir to'liq taom qo'shing.","Diqqat: bugun atigi {k} kkal, bu {min} kkal dan past. Oqsil va uglevodli to'yimli taom bilan kunni yakunlang.","Hozircha {k} kkal yozildi — {min} kkal dan kam. Bunday kam miqdor charchoq keltiradi; yana bir ovqat qo'shishni tavsiya qilaman."],"re_fat":["{name}da {fg} g yog' bor. Keyingi ovqatni yengilroq tanlash yaxshi bo'ladi.","Yog'liroq taom: {name}, {fg} g. Keyingi ovqatga sabzavot yoki qatiq mos keladi.","Yog' miqdori: {name} — {fg} g. Kun davomida yengilroq taomlar muvozanat beradi.","Bu muammo emas: {name} {fg} g yog' qo'shdi, keyingi ovqat yengilroq bo'lsa kifoya.","Keyingi ovqatga bug'da pishgan yoki qaynatilgan taom taklif qilaman — {name}da {fg} g yog' bor edi."],"re_first":["Kunning birinchi ovqati: {name}, {k} kkal. Bugun uchun yana {left} kkal bor.","Yaxshi boshlanish. {name} — {k} kkal; kunlik zaxira {left} kkal.","{name} yozildi, {k} kkal. Bu kunning birinchi yozuvi.","Birinchi ovqat qo'shildi: {name} ({k} kkal). Davom etamiz.","Bugungi hisob ochildi: {name}, {k} kkal. Qolgani — {left} kkal."],"re_goal":["{name} bilan me'yorga deyarli yetdingiz — {left} kkal qoldi.","Yaxshi joydasiz: {name} qo'shildi, me'yorgacha {left} kkal.","Kunlik me'yor deyarli to'ldi. {name}dan keyin {left} kkal qoldi.","Kun yaxshi yakunlanyapti: {name} yozildi, qolgani {left} kkal.","Me'yorga yaqinsiz: {name} bilan qolgan miqdor {left} kkal."],"re_light":["{name} — atigi {k} kkal. Yengil va foydali tanlov.","Juda yaxshi: {name}, {k} kkal. Bunday taomlar kunni muvozanatda tutadi.","Kam kaloriyali va to'yimli: {name}, {k} kkal. Ofarin.","Yengil taom qo'shildi: {name}, {k} kkal. To'g'ri tanlov.","Ratsionga yaxshi qo'shimcha — {name}, {k} kkal. Shunday davom eting."],"re_ok":["{name} qo'shildi: {k} kkal. Me'yor ichidasiz, yana {left} kkal bor.","Yozib qo'ydim — {name}, {k} kkal. Kun uchun {left} kkal qoldi.","Me'yorga yaxshi sig'di: {name} ({k} kkal). Zaxira: {left} kkal.","Hammasi rejadagidek: {name}, {k} kkal. Qolgan miqdor — {left} kkal.","Qo'shildi: {name}, {k} kkal. Siz me'yor ichidasiz, oldinda {left} kkal."],"re_over":["{name} bilan me'yordan {x} kkal oshdi. Bir kun hech narsani buzmaydi — ertaga davom etamiz.","Bugun {x} kkal ortiq bo'ldi ({name}). Xotirjam bo'ling, muhimi — umumiy yo'nalish.","Bunday kunlar bo'ladi: {name} bilan me'yordan {x} kkal yuqori, ertaga odatdagidek.","Me'yor {x} kkalga oshdi — {name}. Tashvishga o'rin yo'q, haftalik natija muhimroq.","{name}dan keyin {x} kkal ortiq. Hech narsa yo'qolmadi, ertaga rejamiz bo'yicha."],"re_pgoal":["{name} bilan bugungi oqsil maqsadi bajarildi: jami {p} g. Juda yaxshi natija.","Oqsil maqsadiga yetdingiz — {p} g. {name} buni yakunladi. Tabriklayman.","Bugun {p} g oqsil: maqsad bajarildi, {name} so'nggi qadam bo'ldi.","Chin dildan quvonaman: {name} bilan oqsil {p} g ga yetdi.","Maqsad bajarildi. {name}dan keyin bugungi oqsil {p} g."],"re_prot":["{name} {pg} g oqsil berdi. Kunlik maqsadga yana {pleft} g qoldi.","Yaxshi oqsil manbai: {name}, {pg} g. Maqsadgacha {pleft} g.","Qolgan {pleft} g ni keyingi ovqatlarda olamiz: {name} {pg} g oqsil berdi.","Oqsil bo'yicha yaxshi qadam: {name}dan {pg} g, maqsadgacha {pleft} g.","Bugungi maqsadgacha {pleft} g: {name} oqsilga boy, {pg} g."],"rt_a":["Yog' maqsaddan {x} g ko'p","Yog': +{x} g ortiqcha","Yog' bugun {x} g oshdi","Yog' me'yordan {x} g yuqori","Ortiqcha yog': {x} g"],"rt_b":["Uglevod ko'p, oqsil kam","Uglevod maqsaddan {x} g ko'p","Oqsil uglevoddan ortda","Oqsilga ko'proq joy bering","Uglevod oldinda: +{x} g"],"rt_c":["Oqsilga yana {p} g","Oqsil maqsadiga {p} g qoldi","Kechga {p} g oqsil qoldi","Oqsil: {p} g yetmayapti","Bugun oqsil {p} g kam"],"rt_d":["Yog' ulushi: {sh} %","Kaloriya joyida, yog' — {sh} %","Tarkibda yog' ko'p","Makrolar nisbati og'gan","Kaloriyaning {sh} % i yog'dan"],"rt_e":["Me'yordan {x} kkal ko'p","Bugun +{x} kkal","Kunlik me'yor {x} kkal oshdi","Me'yordan biroz yuqori","Ortiqcha: {x} kkal"],"rt_f":["Muvozanatli kun","Hamma ko'rsatkich joyida","Kun maqsadga mos o'tdi","Ajoyib muvozanat","Kaloriya va makrolar joyida"],"rt_kam":["Juda kam yeyapsiz","Bugun {k} kkal — juda kam","Xavfsiz chegaradan past","Ovqat yetarli emas","Yana bir taom qo'shing"],"s_day1":["Bu birinchi kuningiz. Bugun ovqatlarni yozib boring — maslahatlar ertadan boshlanadi.","Aniq maslahat berishdan oldin odatlaringizni bilib olay. Bugun shunchaki yozing, ertadan tahlil boshlanadi.","Birinchi kunda maslahat bermayman — avval ma'lumot to'playmiz. Ertadan shaxsiy tavsiyalar chiqadi.","Bugun faqat yozib boring. Ertaga sizning ma'lumotlaringiz asosida birinchi maslahatni beraman.","Tanishuv kuni: bugungi yozuvlar keyingi maslahatlarga asos bo'ladi. Maslahatlar ertadan."],"s_ok":["Hozircha hammasi joyida: bugun {k} / {l} kkal, qolgan zaxira {left} kkal.","Bugun {k} / {l} kkal. Me'yor ichidasiz, yana {left} kkal qoldi.","Ko'rsatkichlar yaxshi: {k} / {l} kkal. Kun oxirigacha {left} kkal bor.","{k} / {l} kkal — reja bo'yicha ketyapsiz. Zaxira: {left} kkal.","Hammasi tartibda: {k} / {l} kkal iste'mol qilindi, {left} kkal hali bor."],"s_wait":["Bugun hali kam ovqat yozildi. Yana {n} ta ovqat kiritsangiz, maslahat beraman.","Aniq maslahat uchun yana {n} ta ovqat yozing.","Kunning manzarasi hali to'liq emas. Yana {n} ta ovqatdan so'ng tahlil qilaman.","Yana {n} ta ovqat kiritilgach, bugungi tarkib bo'yicha tavsiya beraman.","Hozircha ma'lumot oz. Yana {n} ta ovqat qo'shilsa, kun bo'yicha xulosa chiqaraman."],"t_dam":["Dam olish kunlari kaloriya ko'proq. Shanba-yakshanba uchun bitta oddiy qoida yetadi, masalan, shirinlik bir marta.","Shanba va yakshanba ish kunlaridan sezilarli yuqori. Bitta qoida belgilang: masalan, shirinlik kuniga bir marta.","Farq asosan dam olish kunlarida. Hafta oxiriga bitta aniq qoida, masalan, shirinlikni bir marta yeyish, yaxshi ishlaydi.","Men dam olish kunlari ko'proq yeyilganini ko'ryapman. Oddiy qoida — masalan, shirinlik bir marta — shu farqni kamaytiradi.","Hafta oxiri kaloriya oshadi. Shanba-yakshanba uchun bitta qoida tanlang, masalan, shirinlik faqat bir marta."],"t_damOk":["Ish va dam olish kunlari farqi kichik — yaxshi.","Hafta oxiri ish kunlaridan deyarli farq qilmaydi. Barqaror tartib.","Shanba-yakshanba ham kaloriya ish kunlariga yaqin — bu juda yaxshi.","Men ish va dam olish kunlari orasida katta farq ko'rmayapman. Shu tartibni saqlang.","Ovqatlanish hafta davomida bir tekis — dam olish kunlari ham."],"t_ich":["Ichimliklar sezilarli kaloriya beryapti. Shakarli ichimlikni suv yoki shakarsiz choyga almashtirish yaxshi tanlov.","Kaloriyaning bir qismi ichimliklardan. Shakarlisi o'rniga suv yoki shakarsiz choy ichib ko'ring.","Ichimliklardan keladigan kaloriya katta. Eng oson o'zgarish — shakarli ichimlik o'rniga suv yoki shakarsiz choy.","Men ichimliklar hissasini sezilarli deb ko'ryapman. Shakarlilarini suv yoki shakarsiz choyga almashtirish tez farq beradi.","Shakarli ichimliklar kunlik hisobga sezilarli qo'shilyapti. Ularni suv yoki shakarsiz choy bilan almashtirsangiz, yaxshi bo'ladi."],"t_ichOk":["Ichimliklardan kaloriya kam.","Ichimliklar kunlik hisobga deyarli ta'sir qilmayapti — yaxshi.","Ichimliklarda kaloriya oz. Bu yo'nalishda hammasi joyida.","Men ichimliklardan keladigan kaloriyani past ko'ryapman. Shu odatni saqlang.","Ichimliklar bo'yicha tartib yaxshi: kaloriyasi kam."],"t_kechki":["Kunning 40 % dan ko'pi kechki ovqatga to'g'ri keladi. Tushlikni to'yimliroq qilsangiz, kechqurun kamroq ochiqasiz.","Kechki ovqat ulushi 40 % dan yuqori. To'yimli tushlik kechki ishtahani tabiiy ravishda kamaytiradi.","Kaloriyaning katta qismi — 40 % dan ortig'i — kechqurun. Tushlikka oqsil va sabzavot qo'shsangiz, kechki ovqat yengilroq o'tadi.","Men ko'ryapman: kunning 40 % dan ko'pi kechki ovqatda. Tushlikni biroz to'yimliroq qilish eng oddiy yechim.","Kechqurun kunlik kaloriyaning 40 % dan ortig'i yeyilyapti. Tushlik to'yimliroq bo'lsa, kechki ovqatda o'zingizni yengilroq his qilasiz."],"t_kechkiOk":["Kechki ovqat ulushi me'yorida.","Kaloriya kun davomida to'g'ri taqsimlangan, kechki ovqat ortiqcha emas.","Kechki ovqat kunlik hisobda me'yoridan oshmagan — yaxshi tartib.","Men kechki ovqat ulushini me'yorida ko'ryapman. Shu taqsimotni saqlang.","Kechqurun yeyilgan miqdor me'yorida — bu yo'nalishda hammasi joyida."],"t_noMain":["Katta og'ish topilmadi — tartib yaxshi.","Bu davrda jiddiy chetlanish yo'q. Ovqatlanish tartibi barqaror.","Men katta og'ish ko'rmadim. Hozirgi tartibni saqlang.","Tahlil hech qanday katta muammo ko'rsatmadi — yaxshi natija.","Ko'rsatkichlar me'yor atrofida, katta og'ish yo'q."],"t_oqsil":["Oqsil maqsadi kam kunlarda bajarilgan. Nonushtaga tuxum yoki qatiq qo'shish — eng oson yo'l.","Oqsil ko'p kunlarda yetishmagan. Ertalabki tuxum yoki qatiq bu farqni tez to'ldiradi.","Oqsil maqsadiga kamdan-kam yetildi. Nonushtadan boshlash qulay: tuxum yoki qatiq.","Men oqsil maqsadi ko'pincha bajarilmaganini ko'ryapman. Nonushtaga tuxum yoki qatiq qo'shib ko'ring.","Oqsil yetarli bo'lgan kunlar kam. Eng oddiy qadam — har kuni nonushtada tuxum yoki qatiq."],"t_oqsilOk":["Oqsil maqsadi ko'p kunlarda bajarilgan.","Oqsil yetarli bo'lgan kunlar ko'pchilikni tashkil qiladi — yaxshi natija.","Ko'p kunlarda oqsil maqsadiga yetildi. Shu odatni saqlang.","Men oqsil bo'yicha barqaror natija ko'ryapman: maqsad ko'p kunlarda bajarilgan.","Oqsil bo'yicha tartib yaxshi — kunlarning aksariyatida maqsad bajarilgan."],"t_top":["{f} eng ko'p kaloriya bergan. Uning porsiyasini biroz kichraytirish — eng tez natija beradigan qadam.","Eng katta ulush {f}ga to'g'ri keladi. Porsiyani sal kamaytirsangiz, farq tez seziladi.","Asosiy kaloriya manbai — {f}. Uni tashlamasdan, porsiyasini biroz kichikroq qilish yetarli.","Ro'yxat boshida {f} turibdi. Har safar biroz kamroq solish — eng oson va tez yo'l.","Men ko'rgan eng katta ulush — {f}. Porsiyani ozroq kichraytirish boshqa o'zgarishlardan tezroq ish beradi."],"t_wless":["Haqiqiy natija kutilgandan sekinroq. Ko'pincha sabab — suv va tuz (kunlar orasida 1–2 kg tebranish) yoki yozilmagan ovqat.","Natija hisobdan orqada. Odatda bu suv va tuz bilan bog'liq — vazn kunlar orasida 1–2 kg o'zgaradi — yoki ba'zi ovqatlar yozilmagan.","Men haqiqiy natijani kutilgandan sekinroq ko'ryapman. Suv va tuz 1–2 kg farq berishi mumkin; yozilmagan ovqatlarni ham tekshirib ko'ring.","Kutilgan va haqiqiy orasida farq bor. Eng ko'p uchraydigan sabablar: suv va tuz (1–2 kg tebranish) yoki yozilmay qolgan ovqat.","Haqiqiy natija sekinroq. Bu ko'pincha vaqtinchalik: suv va tuz kunlar orasida 1–2 kg farq beradi. Yozilmagan ovqat ham sabab bo'lishi mumkin."],"t_wmore":["Haqiqiy natija kutilgandan tezroq — ko'pincha suv hisobiga; keyingi haftalarda tenglashadi.","Natija hisobdan oldinda. Odatda bu suv bilan bog'liq va keyingi haftalarda barqarorlashadi.","Men haqiqiy natijani kutilgandan tezroq ko'ryapman. Bu ko'pincha suv yo'qotish hisobiga va vaqt o'tib tenglashadi.","Kutilgandan tezroq o'zgarish ko'pincha suvga bog'liq. Keyingi haftalarda raqamlar hisobga yaqinlashadi.","Haqiqiy natija tezroq. Bu odatda vaqtinchalik: suv hisobiga bo'ladi va keyingi haftalarda tenglashadi."],"t_wok":["Kutilgan va haqiqiy natija deyarli bir xil — hisob to'g'ri ishlayapti.","Yozilganlar asosidagi hisob haqiqiy natijaga mos keladi.","Men kutilgan va haqiqiy natijada katta farq ko'rmayapman. Yozuvlar aniq.","Natija hisobga yaqin — demak, ovqatlar to'g'ri yozilgan.","Kutilgan va haqiqiy yo'nalish bir xil. Shu tartibda davom eting."],"t_yog":["Yog' ulushi 45 % dan yuqori. Tepadagi taomlardan birini haftada 1–2 marta yengilrog'iga almashtirish yaxshi boshlanish.","Kaloriyaning 45 % dan ortig'i yog'dan kelyapti. Ro'yxat boshidagi taomlardan birini haftada 1–2 marta yengilroq variant bilan almashtirib ko'ring.","Men yog' ulushini 45 % dan yuqori ko'ryapman. Haftada 1–2 marta yuqoridagi taomlardan biri o'rniga yengilrog'ini tanlash yetarli.","Yog' me'yordan ko'p: 45 % dan yuqori. Eng oson yo'l — tepadagi taomlardan birini haftada 1–2 marta yengilrog'i bilan almashtirish.","Yog'ning ulushi 45 % chegarasidan oshgan. Yuqoridagi ro'yxatdan bitta taomni haftada 1–2 marta yengilroq taomga almashtirsangiz, farq seziladi."],"t_yogOk":["Yog' ulushi me'yorga yaqin. Hozircha bu yerda hech narsani o'zgartirmasak ham bo'ladi.","Yog' miqdori me'yor atrofida — yaxshi muvozanat.","Kaloriyada yog'ning ulushi to'g'ri darajada.","Men yog' ulushini me'yorga yaqin ko'ryapman. Shu tartibni saqlang.","Yog' bo'yicha hammasi joyida: ulushi me'yordan uzoqlashmagan."],"t_yoz":["Bir necha kun yozilmagan yoki chala. Hisob aniq bo'lishi uchun har kuni hech bo'lmasa asosiy ovqatlarni yozing.","Ba'zi kunlarda yozuv yo'q yoki to'liq emas. Har kuni asosiy ovqatlarni yozib borish tahlilni ishonchli qiladi.","Yozilmagan va chala kunlar bor. Asosiy ovqatlarni har kuni yozsangiz, raqamlar to'g'ri chiqadi.","Men bir necha kunni chala ko'ryapman. Har kuni asosiy ovqatlarni yozish hisobni aniqroq qiladi.","Bir qancha kunlar to'liq yozilmagan. Kuniga bir necha soniya — asosiy ovqatlarni yozish — tahlil aniqligini oshiradi."],"t_yozOk":["Kunlar deyarli to'liq yozilgan.","Yozuvlar deyarli to'liq — tahlil ishonchli.","Deyarli har kun yozilgan, shuning uchun raqamlar aniq.","Men kunlarni deyarli to'liq ko'ryapman. Shu odatni saqlang.","Yozib borish tartibi yaxshi: bo'sh kunlar deyarli yo'q."],"x_nx0":["Ertaga ham shu tartibda davom eting","Ertaga ham bugungi rejani saqlang","Ertaga ham shunday muvozanatda ovqatlaning","Ertaga ham shu odatlarni davom ettiramiz","Ertaga ham xuddi bugungidek"],"x_nxC":["Ertaga nonni yarim bo'lakka qisqartiring","Ertaga non — yarim bo'lak","Ertaga nonni yarmiga kamaytirsak yaxshi","Ertaga har ovqatda yarim bo'lak non yetarli","Ertaga nonni kamroq oling: yarim bo'lak"],"x_nxF":["Ertaga tushlikka tovuq yoki baliq tanlang","Ertaga tushlikda yog'sizroq oqsil: tovuq yoki baliq","Ertangi tushlik uchun tovuq yoki baliq yaxshi tanlov","Ertaga tushlikni tovuq yoki baliq bilan rejalang","Ertaga tushlikda qovurilgan emas, tovuq yoki baliq"],"x_nxK":["Ertaga kechki ovqatni kichikroq likopchada","Ertaga kechki porsiyani biroz kichraytiring","Ertaga kechki ovqat yengilroq va kichikroq bo'lsin","Ertaga kechqurun kichik likopcha tanlang","Ertaga kechki ovqatni ixchamroq qilsak yaxshi"],"x_nxLow":["Ertaga 3 mahal to'yimli ovqat — nonushtani tashlab ketmang","Ertaga nonushta, tushlik va kechki ovqatni to'liq qiling","Ertaga uch mahal muntazam ovqatlanaylik","Ertaga nonushtadan boshlab, kun bo'yi me'yorida ovqatlaning","Ertaga ovqatni tashlab ketmaslikka harakat qiling"],"x_nxP":["Ertaga nonushtaga tuxum yoki qatiq qo'shing","Ertaga nonushtada oqsil: tuxum yoki qatiq","Ertangi nonushta uchun tuxum yoki qatiq yaxshi tanlov","Ertaga nonushtani tuxum yoki tvorog bilan boshlang","Ertaga nonushtaga oqsilli taom: tuxum, qatiq yoki tvorog"],"x_off0":["Og'ish yo'q — hammasi maqsad atrofida","Barcha ko'rsatkichlar me'yorda","Sezilarli og'ish bo'lmadi","Maqsaddan chetlanish yo'q","Kun rejaga mos o'tdi"],"x_offC":["Uglevod {x} g ko'p — {src}","Uglevod maqsaddan {x} g oshdi: asosan {src}","Uglevod bo'yicha +{x} g — manbasi: {src}","Uglevod {x} g ortiqcha","Uglevod me'yordan {x} g yuqori bo'ldi"],"x_offF":["Yog' {x} g ko'p — {src}","Yog' maqsaddan {x} g oshdi: asosan {src}","Yog' bo'yicha +{x} g — manbasi: {src}","Yog' {x} g ortiqcha","Yog' me'yordan {x} g yuqori bo'ldi"],"x_offK":["Me'yordan {x} kkal ko'p — {src}","Kaloriya me'yordan {x} kkal oshdi: asosan {src}","+{x} kkal me'yordan — manbasi: {src}","Kaloriya {x} kkal ortiqcha","Kunlik me'yordan {x} kkal yuqori"],"x_offLow":["Juda kam yedingiz: {k} kkal (xavfsiz chegara {min})","{k} kkal — bu xavfsiz chegara ({min}) dan past","Iste'mol juda kam: {k} kkal, eng kami {min} kkal","Bugun {k} kkal — xavfsiz {min} kkal chegarasidan kam","Kaloriya juda past: {k} (xavfsiz chegara — {min})"],"x_offP":["Oqsil {x} g yetmadi","Oqsil maqsaddan {x} g kam bo'ldi","Oqsil yetishmovchiligi: {x} g","Oqsil bo'yicha {x} g kamomad","Oqsil maqsadiga {x} g yetmay qoldi"],"x_okK":["Kaloriya me'yorda: {v} / {g} kkal","Kunlik kaloriya chegarada: {v} / {g} kkal","{v} / {g} kkal — me'yordan chiqilmadi","Kaloriya maqsad doirasida: {v} / {g} kkal","Me'yorga rioya qilindi: {v} / {g} kkal"],"x_okN":["{n} ta ovqat yozildi — hisob aniq","Bugun {n} ta ovqat qayd etildi","Yozuvlar: {n} ta — hisob to'liq","{n} ta ovqat kiritildi, ma'lumot ishonchli","Kun bo'yi {n} ta yozuv — tahlil aniq"],"x_okP":["Oqsil maqsadi bajarildi: {v} / {g} g","Oqsil yetarli: {v} / {g} g","Oqsil bo'yicha maqsadga yetdingiz: {v} / {g} g","{v} / {g} g oqsil — maqsad bajarildi","Oqsil me'yorda: {v} g, maqsad {g} g"],"x_okS":["Qadam: {v}","Bugungi qadamlar: {v}","{v} qadam yurildi","Faollik: {v} qadam","Kunlik qadam soni: {v}"],"x_okW":["Suv maqsadi bajarildi: {v} ml","Suv yetarli ichildi: {v} ml","{v} ml suv — kunlik maqsad bajarildi","Suv me'yorda: {v} ml","Kunlik suv: {v} ml — maqsadga yetdingiz"]}},"ru":{"hazil":{"c_noon":["Уже полдень, а тарелка всё пустая. Завтрак был?","Привет! Список сегодня подозрительно тихий. Что-нибудь ели?","Полдня прошло, а я ещё ни одного блюда не видела. Всё хорошо?","Даже чайник интересуется: что сегодня было на завтрак?","Обеденный час! С утра что-то ели или просто забыли записать?"],"cel_day":["Ура-ура! {k} / {l} ккал — день точно в норме.","В яблочко! {k} / {l} ккал — день на пятёрку.","{k} / {l} ккал — точно, как часы. Браво!","День закончился красиво: {k} / {l} ккал. Я очень-очень рада!","Вот это точность! {k} / {l} ккал. Отличный день."],"cel_p":["Ура! Белок сегодня {p} / {g} г — цель выполнена!","Белковая вершина покорена: {p} / {g} г.","{p} г белка! План на сегодня выполнен, браво.","Вот это результат: {p} / {g} г белка. Радуюсь!","Белок сегодня в полном комплекте: {p} г. Празднуем!"],"d_empty":["В тот день дневник пустует — видимо, тоже отдыхал.","Здесь записей нет. Дневнику тоже иногда нужен отпуск.","Тот день — чистая страница. Ничего, следующие заполнятся.","Этот день не записан — остался загадкой.","В тот день записей не было — бывает и такое."],"d_low":["В тот день еды было совсем мало — или что-то не попало в записи.","Этот день вышел очень лёгким. Всё ли записано, или тарелка спряталась?","В тот день заметно меньше нормы. Надеюсь, вы просто забыли что-то внести.","Калорий здесь мало — возможно, запись просто ускользнула.","В тот день ели мало. Забота о себе начинается с регулярной еды."],"d_ok":["Тот день в норме — образцовый!","Этот день можно вешать в рамочку: всё в норме.","В тот день тарелка и цель говорили на одном языке.","Этот день попал точно в цель — браво!","Тот день прошёл в равновесии. Побольше бы таких!"],"d_over":["В тот день вышло на {x} ккал больше нормы — видимо, был праздник.","Этот день прошёл с запасом в {x} ккал. Один день ничего не решает.","+{x} ккал — в тот день дастархан был щедрым. Ничего страшного.","В тот день норма превышена на {x} ккал. Бывают и такие дни.","Здесь плюс {x} ккал. Это уже прошлое — важнее следующие дни."],"g_day":["Привет! День в разгаре, обед уже занимает очередь.","Я тут, присматриваю за вашей тарелкой. Как день?","Привет-привет! Середина дня — время для чая и хорошего обеда.","Снова вы! Полдня позади — как там дела?","Дневной привет! Заглянем в сегодняшнее меню?"],"g_evening":["День был долгим, а ужин уже ждёт своего часа.","Вечер добрый! С кухни уже пахнет чем-то вкусным?","Привет! День на финишной прямой — заварим чай и подведём итоги.","Вечереет, а я всё ещё на вашей стороне.","Тарелка готовится к последнему акту дня. Занавес скоро!"],"g_morning":["Чайник уже шумит, а я придумываю для вас хороший день!","С добрым утром! Завтрак сегодня в главной роли — ждёт выхода на сцену.","Утро доброе, ранняя пташка! Солнце и я уже на месте.","Тарелка пока пустая, но настроение у неё отличное. Утречко!","Проснулись? Интересно, кто сегодня первым попадёт в список."],"g_night":["Ночь на дворе! Подушка, кажется, уже скучает по вам.","Доброй ночи! Завтрак после хорошего сна всегда вкуснее.","Не спится? Даже луна начала зевать.","Поздно уже. Телефон отдыхает, я отдыхаю — давайте и вы.","Ночной привет! Звёзды вышли, значит, и сон где-то рядом."],"m_eve":["В {n} из последних дней ужин забирал главную роль. Сделаем обед посытнее?","Ужин — звезда программы в {n} из последних дней. Давайте уделим внимание обеду.","Вечерняя тарелка была самой большой в {n} из последних дней. Плотнее обед — легче вечер.","Вечерний дастархан побеждал в {n} из последних дней. Добавим белка в обед и уравняем счёт.","Счёт по последним дням: ужин лидирует — {n}. Сытный обед облегчит вечер."],"m_fat_better":["Вчера жира было на {x} г больше, а сегодня — гораздо лучше. Браво!","Вчерашний жирный день позади — сегодня намного легче. Здорово!","Сегодня всё по порядку, а вчера жир обогнал цель на {x} г. Нравится!","Жир вчера немного разбежался, сегодня успокоился. Отлично!","От вчерашних лишних {x} г жира ни следа. Вот это возвращение!"],"m_kcal_better":["Вчера было +{x} ккал, а сегодня всё на своих местах. Здорово!","Вчерашний день позади — сегодня норма на месте. Браво!","Ровно! Вчера счёт ушёл вверх на {x} ккал, а сегодня порядок.","Баланс, который вчера сбежал, сегодня вернулся. Прекрасно!","Забыли вчерашние {x} ккал — сегодня всё по плану."],"m_prot3":["Уже {n}-й день белок не дотягивает до цели. Добавим к завтраку яйцо?","Белок {n}-й день ждёт своей очереди. На обед — курица или рыба?","{n}-й день подряд белок не доходит до финиша. Пусть сегодня выручат катык и яйца.","Выведем белок на сцену — {n}-й день он скромно стоит в сторонке. Курица или рыба?","Утром яйцо, в обед рыба — и {n}-й день без нормы белка станет последним."],"m_pstreak":["Белок с вами явно подружился: цель выполнена {n}-й день подряд!","Белковая серия: {n}-й день! Очень круто.","Уже {n}-й день белок на финише. Вы мастер белка!","{n}-й день подряд белок на месте — это настоящая привычка.","Пятёрка по белку {n}-й день подряд. Вперёд!"],"m_skipbf":["Завтрак не записан в {n} из последних 5 дней. Может, начнём утро с пиалы катыка?","Отпуск у завтрака затянулся: {n} из 5 дней. Вернём его завтра яйцом с лепёшкой?","В {n} из 5 дней утренняя тарелка пустовала. Лёгкий завтрак — хороший старт.","Прогульщик-завтрак: {n} из 5 дней. Завтра позовём его кашей или яйцом.","Пропущенных завтраков за последние дни: {n}. Утром чай с кусочком сыра — уже завтрак."],"m_streak":["{n}-й день подряд в норме! Это уже привычка. Вперёд!","Серия растёт: {n}-й день в норме! Я горжусь.","Уже {n}-й день счёт на месте. Вы меня вдохновляете!","Вот это серия: {n}-й день в норме. Добавим ещё один?","Точно, ровно, красиво — {n}-й день подряд. Идём отлично!"],"mk_c_bajarildi":["Углеводы план выполнили — хлеб и каша сегодня отлично поработали.","Углеводы у цели. Запас энергии полон!","Углеводы нашли своё место. День в равновесии.","Углеводы попали в яблочко. Так держать!","Углеводы сегодня дисциплинированы — ровно в цель."],"mk_c_deyarli":["Углеводы подходят к финишу — ещё {left} г. Одно яблоко закроет вопрос.","Углеводы почти у цели. Лишний хлеб сегодня может отдохнуть.","До цели по углеводам {left} г — горсть ягод сделает последний шаг.","Углеводы уже видят финиш. Сладкое можно отложить на завтра.","До конца плана по углеводам чуть-чуть: {left} г. Добавка хлеба теперь в зрителях."],"mk_c_kam":["Углеводов пока мало — за день их подвезут хлеб, каша или фрукты.","Углеводы ещё в пути: свободно {left} г. Фрукт или каша их поторопят.","Для углеводов {left} г свободного места. Гречка или яблоко его займут.","Углеводы не спешат. Кусочек хлеба или рис могут их подогнать.","В плане по углеводам много места. Фрукты, каши, хлеб — до вечера без спешки."],"mk_c_oshdi":["Хлеб сегодня в главной роли — углеводов на {x} г больше. В следующий раз хватит полкуска.","Углеводов плюс {x} г. Самый простой шаг — урезать хлеб до полкуска.","Углеводы сегодня пришли с запасом в {x} г. Полкуска хлеба вместо целого — и порядок.","Лишние {x} г углеводов — договоримся с хлебом на полкусочка.","Сладкое и хлеб сегодня активны: +{x} г углеводов. Полкуска хлеба вернут баланс."],"mk_f_bajarildi":["План по жирам закрыт. Жирным блюдам сегодня говорим «спасибо, хватит».","Жиры у цели — казы и манты подождут до завтра.","Жиры получили свою долю. Теперь очередь лёгких блюд.","Жиры на месте. Сцена для жирного на сегодня закрыта.","Жиры около цели — масляный бал на сегодня можно завершить."],"mk_f_deyarli":["Жиры подбираются к цели — ещё {left} г. Дополнительное масло сегодня отдыхает.","Жиры почти у цели. Сливочному маслу можно дать выходной.","До цели по жирам {left} г — этот зазор еда закроет сама, без лишнего масла.","Жирам осталось совсем немного. Сметана сегодня пусть посидит в зрителях.","Жиры почти на месте: {left} г. На каплю меньше масла в салат — и красота."],"mk_f_kam":["Жиров пока мало — и это хорошая новость. До вечера они найдут дорогу сами.","Жиры сегодня скромничают: в запасе ещё {left} г. Специально добавлять незачем.","Жиры ещё не вышли на сцену — и прекрасно. С обычной едой они подтянутся сами.","Для жиров свободно {left} г. Не волнуйтесь, они всегда приходят сами.","Жиров маловато — не страшно. Масло и орешки за день внесут свою долю."],"mk_f_oshdi":["Жиры сегодня задержались в гостях на {x} г. В следующий раз — курица, рыба или овощи.","Жиры перевыполнили план на {x} г — следующую тарелку доверим курице или рыбе.","Масло сегодня расщедрилось: плюс {x} г. Теперь очередь овощей и рыбы.","Жиров на {x} г больше. Лёгкий ужин из курицы и салата вернёт равновесие.","Плюс {x} г жиров — ничего страшного. Следующее блюдо понежирнее: рыба или овощи."],"mk_p_bajarildi":["Белок план выполнил: {v}/{g} г. Сытость теперь с вами надолго.","Белок сегодня на пятёрку — {v}/{g} г. До вечера будет сытно.","Цель по белку взята! Сытость теперь никуда не торопится.","{v}/{g} г — белок своё дело сделал. Аппетит тоже станет спокойнее.","Белок дошёл до финиша. Теперь он надолго сохранит сытость."],"mk_p_deyarli":["Белок почти у финиша: ещё {left} г. Одно яйцо красиво закроет вопрос.","Совсем чуть-чуть — {left} г белка. Стакан катыка сделает последний шаг.","Белок уже видит цель: осталось {left} г. Ломтик сыра дотянет.","Ещё {left} г — и белок дойдёт до цели. Творог с радостью поможет.","Белок почти дома: {left} г в пути. Горсть нута или яйцо — и готово."],"mk_p_kam":["Белок пока стесняется: ещё {left} г. Яйцо, катык или курица его подбодрят.","Белок ждёт своей очереди — осталось {left} г. Рыба или нут помогут.","До цели по белку {left} г. Курица, творог или фасоль спешат на помощь.","В тарелке маловато белка: ещё {left} г. Яйцо и стакан катыка — отличная пара.","Белку не хватает компании — ещё {left} г. Пригласите рыбу, яйца или маш."],"mk_p_oshdi":["Белок сегодня старался с энтузиазмом — на {x} г сверх цели. Не беда, приглядывайте за калориями.","Белок перевыполнил план на {x} г. Вреда нет, а калории пусть остаются под присмотром.","Белок отработал две смены. Обычно это хорошо — только калории держите в поле зрения.","Белка с запасом: на {x} г больше цели. Волноваться не о чем, загляните в счёт калорий.","Белок расщедрился — плюс {x} г. Обычно это не вредит, лишь бы калории не убежали."],"q_full":["Ну как, желудок доволен? Чувствуете сытость?","Как ощущения — вы сыты?","Тарелка справилась? Вы наелись?","Вопросик: после сегодняшней еды вы сыты?","Что говорит внутренний голос — сытно?"],"q_mood":["Ну что, как день проходит?","Какая сегодня погода в настроении: солнечно?","Как вам сегодняшний день — нравится?","Один вопрос: как настроение сегодня?","День вас балует или утомляет?"],"qr_full_mid":["Для лёгкого перекуса есть место — {left} ккал. Катык или яблоко подойдут.","Средне? Тогда пиала катыка или фрукт — отличное дополнение.","Немного места осталось: {left} ккал. Фрукты уже стоят в очереди.","Если хочется, что-то лёгкое — катык или горсть ягод.","В запасе {left} ккал. Для маленького перекуса катык — то, что надо."],"qr_full_no":["Поняла! В запасе {left} ккал — яйцо или катык отлично выручат.","Аппетит проснулся? Есть {left} ккал, курица или творог справятся.","Ничего страшного, {left} ккал ваши. Возьмём что-то белковое — яйцо, катык.","Вот решение: в пределах {left} ккал — творог или варёное яйцо.","Можно ещё — есть {left} ккал. Курица или катык надолго дают сытость."],"qr_full_yes":["Отлично! Если сыты — не доедайте через силу, тарелка подождёт.","Прекрасно! Чувствовать сытость — настоящая суперсила.","Поняла! Мне нравится, как вы слушаете себя.","Остальное отложим — еда никуда не убежит.","Вот это навык! Сказать «хватит» и остановиться — уровень чемпиона."],"qr_mood_bad":["Эх... Сегодня мои советы будут помягче. Берегите себя.","Поняла. Сегодня цифры на втором месте, вы — на первом.","Бывают такие дни. Я сегодня буду тише и мягче.","Обнимаю! Сегодня никакого давления, советы будут лёгкими.","Слышу вас. Сегодня цифры отдыхают, а мои советы — только мягкие."],"qr_mood_good":["Отлично! Когда у вас хорошее настроение, я тоже радуюсь.","Ура! Сегодня день на вашей стороне.","Прекрасно! Сохраним это солнечное настроение до вечера.","Как приятно слышать! Пусть сегодня всё идёт легко.","Вот это новость! Пусть день так и продолжается."],"qr_mood_ok":["Средние дни тоже бывают — я рядом.","Ладно, не каждый день праздник. Чашка чая часто помогает.","Бывают и такие дни. До вечера ещё может случиться что-то хорошее.","Поняла. Давайте сегодня будем к себе чуточку добрее.","Средне — это тоже неплохо. Я здесь, продолжаем вместе."],"r_a":["Жиры сегодня разогнались на {x} г — главный вклад: {src}. Следующую тарелку отдадим курице или рыбе.","{Src} — и вот жиров на {x} г больше. Ничего, ужин с рыбой или курицей вернёт равновесие.","Жиры вырвались вперёд на {x} г. Теперь очередь нежирного белка: курица, рыба и побольше овощей.","Плюс {x} г жира, и почти всё — {src}. На следующий приём пищи предлагаю курицу с овощами.","Жиры сегодня гуляют: +{x} г сверх плана. Рыба или курица с салатом спокойно всё выровняют."],"r_b":["Хлеб сегодня в главной роли: углеводы +{x} г, а белку не хватает {p} г. Следующий выход — за яйцами или катыком.","Углеводы в гонке впереди на {x} г, белок отстал на {p} г. Поможем ему курицей или яйцом.","Тесто захватило тарелку: +{x} г углеводов. Белок ждёт своей очереди — ещё {p} г, тут отлично подойдут катык или яйцо.","Главный вклад в углеводы: {src}, и их уже +{x} г. Белку осталось {p} г — давайте поменяем кусок лепёшки на яйцо.","Весы качнулись к углеводам (+{x} г), белок пока скромно ждёт {p} г. Чуть меньше хлеба, чуть больше курицы — и равновесие."],"r_c":["Белок ещё ждёт {p} г. Порадуем его на ужин курицей или рыбой.","День близится к финалу, а белку нужно {p} г. Ужин — решающий раунд: на сцену выходят курица и катык.","В графе «белок» свободно {p} г. Предлагаю заполнить её рыбой или парой яиц.","До финиша по белку {p} г. Пиала катыка или омлет — и ленточка ваша.","Вечер, а белок всё ещё ждёт свои {p} г. Курица на ужин закроет вопрос."],"r_d":["Калории в норме, но жиры заняли {sh} % тарелки. Завтра дадим больше места белку — с ним сытость дольше.","Цифра красивая, а состав перекошен: {sh} % — жиры. Белок тоже просит слова, и сытость с ним держится дольше.","Главный вклад — {src}, и доля жиров уже {sh} %. В следующий раз пусть и белок получит своё: с ним сытость дольше.","Жиры сегодня тянут одеяло на себя — {sh} % калорий. Завтра на завтрак яйца или творог, и баланс вернётся.","Счёт в порядке, но жиры правят бал: {sh} %. Добавим завтра курицы или рыбы — и сытость продержится дольше."],"r_e":["Сегодня стол был щедрым: +{x} ккал. Один день ничего не решает — завтра ограничим сладкое одним кусочком.","Главный вклад сегодня — {src}, норма растянулась на {x} ккал. Не страшно: завтра тарелка на ужин чуть поменьше.","+{x} ккал — бывают и праздничные дни. План на завтра простой: одну еду дополним овощами.","День вышел сытным, на {x} ккал выше нормы. Завтра 15 минут прогулки — и ногам приятно, и счёту.","Норма сегодня чуть раздвинулась, всего на {x} ккал. Результат от одного дня не меняется; попробуем завтра чай без сахара?"],"r_f":["Белки, жиры, углеводы — все трое договорились. Сегодня тарелка получает пятёрку!","Сегодня всё попало точно в цель. Я прямо радуюсь — какой день!","Красивый счёт, красивая тарелка, красивый день. Продолжаем в том же духе!","Вот это баланс! Калории и макросы стоят ровно на своих местах. Я вами горжусь.","Сегодня все показатели проголосовали «за». Повторим такой день завтра?"],"r_kam":["Сегодня пока {k} ккал, а безопасный минимум — {min} ккал. Пожалуйста, добавьте ещё одну сытную еду, я за вас переживаю.","Уже вечер, а у вас всего {k} ккал — меньше, чем {min} ккал. Тарелка горячего ужина сейчас будет очень кстати.","{k} ккал на сегодня — это совсем немного, нижняя граница {min} ккал. Давайте сделаем ужин сытным и вкусным.","Я на вашей стороне, но {k} ккал — слишком мало: безопасная граница {min} ккал. Перекусите ещё чем-нибудь питательным.","В счёте пока {k} ккал, это ниже {min} ккал. Чтобы завтра были силы, добавьте ещё одну вкусную и сытную еду."],"re_fat":["{name}: {fg} г жира — щедро! Следующий приём сделаем полегче, и день выровняется.","Жира в этот раз {fg} г ({name}). Ничего страшного, на следующий раз предложу овощи.","Следующую тарелку сделаем полегче? {name} добавляет {fg} г жира.","Вкусно, но жирненько: {name}, {fg} г жира. Следующий приём уравновесим салатом.","Отдадим следующую очередь овощам и катыку? Тут {fg} г жира ({name})."],"re_first":["День открыт! {name} — {k} ккал, первым номером. Впереди ещё {left} ккал.","Вот и старт! {name} ({k} ккал) открывает сегодняшний список.","Первый шаг: {name}, {k} ккал. На день ещё {left} ккал.","{name} выходит на сцену первым — {k} ккал. Аплодисменты!","Записала! {name}, {k} ккал — отличное начало, осталось {left} ккал."],"re_goal":["{name} — и мы почти у цели: осталось {left} ккал. Отличное место!","Почти приехали: {name} в списке, ещё {left} ккал.","Красиво подводим день к норме: {name}, до неё {left} ккал.","План дня почти собран: осталось {left} ккал. {name} — в самый раз!","До финиша рукой подать! {name}, и осталось {left} ккал."],"re_light":["Всего {k} ккал! {name} — легко и полезно, отличный выбор.","Лёгкость в чистом виде: {name}, только {k} ккал. Тарелка говорит спасибо.","Самый приятный гость сегодня: {name}, {k} ккал.","Витаминов прибавилось: {name}, всего {k} ккал. Браво!","Вот это лёгкость! {name} — {k} ккал, а пользы много."],"re_ok":["{name} в списке, {k} ккал. Всё в порядке, ещё {left} ккал в запасе.","Отлично, {name} ({k} ккал) на месте. В копилке ещё {left} ккал.","Тарелка довольна: {name}, {k} ккал, а в запасе ещё {left} ккал.","Принято: {name}, {k} ккал. День ждёт ещё {left} ккал.","Хороший выбор! {name} — {k} ккал, впереди ещё {left} ккал."],"re_over":["{name} — и мы вышли за норму на {x} ккал. Ничего, один день ничего не ломает.","Сегодня вышло чуть щедрее — +{x} ккал ({name}). Завтра вернёмся в колею.","Ладно, день один: {name} — плюс {x} ккал к норме, завтра продолжаем.","Счёт выше нормы на {x} ккал ({name}). Не переживайте, завтра новая страница.","+{x} ккал сверху ({name}). Один такой день ничего не меняет, едем дальше!"],"re_pgoal":["Ура! {name} — и цель по белку выполнена: {p} г!","Финиш! Последний кирпичик — {name}, итого {p} г белка.","Пояс чемпиона ваш: {p} г белка, а {name} — решающий ход.","Вот это день! {name} — и белок дошёл до {p} г. Я так рада!","План по белку выполнен! {p} г, финальная точка — {name}."],"re_prot":["Белок на борту: {name}, {pg} г! До цели ещё {pleft} г.","В белковую команду вступает {name} — {pg} г. Осталось {pleft} г, догоним.","Вот это разговор! {name} — это {pg} г белка. Ещё {pleft} г.","{name} — чемпион по белку: {pg} г. До финиша {pleft} г.","Белковый счётчик радуется: +{pg} г ({name}). Ещё {pleft} г."],"rt_a":["Жиры вырвались вперёд: +{x} г","Жиры сегодня щедрые: +{x} г","Жиров с запасом: +{x} г","Жиры разогнались на {x} г","Жиры обогнали план на {x} г"],"rt_b":["Хлеб сегодня в главной роли","Углеводы впереди, белок ждёт","Тесто захватило тарелку","Белок ждёт своей очереди","Углеводы на {x} г в отрыве"],"rt_c":["Белок ждёт ещё {p} г","На ужин — {p} г белка","До финиша по белку {p} г","{p} г белка в очереди","Белок просит ещё {p} г"],"rt_d":["Жиры заняли {sh} % тарелки","Жиры тянут одеяло на себя","Цифра в норме, состав — нет","Жиры правят бал: {sh} %","Жирам досталось много места"],"rt_e":["Стол был щедрым: +{x} ккал","Сегодня праздник: +{x} ккал","Норма чуть растянулась","День удался: +{x} ккал","Щедрый день: +{x} ккал"],"rt_f":["Тарелка на пятёрку","Макросы договорились","День в яблочко","Баланс как по нотам","Идеальный расклад"],"rt_kam":["Тарелка вас ждёт","Сегодня совсем мало еды","Найдётся место для ужина","Пока всего {k} ккал","Давайте ещё поедим"],"s_day1":["Сегодня день знакомства. Просто записывайте — советы начну с завтрашнего дня.","Первый день я только наблюдаю и запоминаю. Заговорю завтра.","Сегодня вы пишете, а я веду конспект. Советы — с завтрашнего дня.","Мы пока только знакомимся. Записывайте, а завтра я приготовлю первый совет.","Первый день — без экзаменов. Просто записывайте, завтра поговорим."],"s_ok":["Пока всё отлично: {k} / {l} ккал. В запасе ещё {left} ккал — можно не спешить.","День идёт гладко: {k} / {l} ккал. В кошельке ещё {left} ккал.","{k} / {l} ккал — я спокойна. Вас ждут ещё {left} ккал.","Счёт спокойный: {k} / {l} ккал. Для следующей еды есть {left} ккал.","На сцене порядок: {k} / {l} ккал, запас {left} ккал. Так держать!"],"s_wait":["Я пока слушаю. Осталось записей: {n} — и совет готов.","Тарелка пока полупустая. Записей до совета: {n}.","Совет ещё томится на огне. Добавьте записей: {n} — и подам горячим.","Хрустального шара у меня нет, только подсчёт. Запишите ещё что-нибудь ({n} из 2) — и скажу точно.","Картина дня только проявляется, до совета записей — {n}. Я рядом и жду."],"t_dam":["По выходным стол празднует — съедается больше. На субботу и воскресенье хватит одного простого правила: например, сладкое один раз.","В выходные тарелка тоже отдыхает, только становится больше. Одно правило всё решит — скажем, сладкое один раз в день.","К выходным еды прибывает, будто ждём гостей. Придумаем одно простое правило — например, сладкое один раз.","Я заметила: в выходные стол расширяется. Одно правило на субботу и воскресенье — сладкое один раз — и вопрос закрыт.","В будни порядок отличный, в выходные — праздник. Добавим одно простое правило, например сладкое один раз, — и хватит."],"t_damOk":["Понедельник и воскресенье в одном ритме — стол и в выходные держит порядок.","Выходные не превратились в праздник тарелки — разница небольшая. Хорошо.","Будни и выходные почти близнецы. Так и оставим.","Я проверила: суббота с воскресеньем тоже прошли спокойно. Отличный результат.","Даже в выходные стол спокоен — разница совсем маленькая."],"t_ich":["Напитки тихонько вносят солидный вклад. Сладкие заменим водой или чаем без сахара — пусть тоже поскромничают.","Калорий в стакане не видно, но в счёте они есть. Вода или чай без сахара вместо сладкого — лёгкая замена.","Напитки в этом периоде соревнуются с блюдами. Можно отдать место сладких воде или чаю без сахара.","Я заметила: часть калорий приезжает в стакане. Заменим сладкий напиток водой или чаем без сахара?","Сладкий напиток — маленький, но заметный пассажир. Вода или чай без сахара вместо него — и счёт сразу легче."],"t_ichOk":["Стакан калорий не возит — от напитков совсем немного. Отлично.","Напитки в этом периоде скромные: калорий почти нет.","Чай и вода делают своё дело — калорий из напитков мало.","Я проверила: из стакана калорий почти не приходит. Прекрасный выбор.","Напитки в счёте почти незаметны — пусть так и будет."],"t_kechki":["Ужин в этом периоде — главный герой: больше 40 % дня. Дадим обеду роль побольше — и вечером будет спокойнее.","Больше 40 % дня приходится на ужин — он тянет всё на себе. Сытный обед заметно его разгрузит.","Вечерний стол щедрый: больше 40 % дня. Если обед будет посытнее, аппетит вечером станет скромнее.","Я заметила: день у вас разгоняется к вечеру — на ужин больше 40 %. Сытный обед выровняет очередь.","Обед скромничает, а ужин празднует: больше 40 % дня. Сделаем обед сытнее — вечером меньше потянет к еде."],"t_kechkiOk":["Ужин вовремя и в своём размере — день поделён по-честному.","Вечерний стол в норме: каждому приёму пищи досталось по справедливости.","Ужин в этот раз не тянул одеяло на себя — доля в норме. Отлично.","Я проверила: и днём, и вечером всё на своих местах. Равновесие.","Ужин скромный и правильный: доля в норме. Так держать."],"t_noMain":["Больших отклонений нет — тарелка в порядке. В этот раз я просто аплодирую.","Искала, искала — большой проблемы не нашла. Режим хороший.","В этом периоде ни одно блюдо не скандалило — отклонений нет, порядок.","Анализ вышел скучным, и это отличный знак: больших отклонений нет.","За столом тишина: крупных отклонений не нашлось. Так и продолжаем."],"t_oqsil":["Белок ждёт своей очереди — цель выполнялась редко. Яйцо или катык на завтрак пропустят его вперёд.","Белок в этом периоде заходил в гости, а не жил. Яйцо или катык утром — самый простой способ его прописать.","Цель по белку часто не доходила до финиша. Утреннее яйцо или катык подбросят её до места.","Я заметила: белок редко добирался до цели. Одно яйцо или пиала катыка на завтрак — и он найдёт своё место.","Белок на тарелке пока стоит в сторонке — цель выполнялась редко. Добавим к завтраку яйцо или катык?"],"t_oqsilOk":["Белок приходил вовремя — цель выполнена в большинстве дней. Отличная команда.","Белок в этом периоде — самый дисциплинированный участник: почти каждый день у цели.","С белком крепкая дружба: цель выполнялась в большинстве дней.","Я проверила: белок почти каждый день добегал до финиша. Прекрасно.","Белок на тарелке уже не гость, а хозяин. Цель выполнена в большинстве дней."],"t_top":["{f} у вас в главной роли. Давайте роль оставим, а порцию чуть уменьшим — это самый быстрый результат.","Чемпион по калориям — {f}. С пьедестала не снимаем, просто порция будет чуть скромнее.","{f} каждый раз забирает больше всех. Чуть меньшая порция — и результат придёт быстрее.","Я посчитала: главная звезда тарелки — {f}. Тарелочку чуть поменьше — и дело пойдёт быстрее.","Знакомьтесь, лидер списка: {f}. Ему хватит и порции чуть поменьше, а вам это даст самый быстрый сдвиг."],"t_wless":["Результат идёт неторопливо. Обычно дело в воде и соли — весы гуляют на 1–2 кг от дня ко дню. Или в еде, что не попала в дневник.","Реальный результат отстаёт от ожидаемого. Чаще всего это игра воды и соли (1–2 кг туда-сюда) или незаписанное блюдо.","Весы пока не догнали расчёт. Причина обычно в воде и соли — колебания на 1–2 кг — или в забытой записи.","Вышло медленнее, чем я ждала. Как правило, причина — вода и соль (1–2 кг между днями) или пара незаписанных приёмов пищи.","Результат не спешит. Часто это просто колебания воды и соли — около 1–2 кг — или блюдо, сбежавшее из дневника."],"t_wmore":["Результат побежал быстрее, чем ожидалось. Чаще всего это вода — в следующие недели всё выровняется с расчётом.","Весы немного поторопились. Обычно причина в воде, и в ближайшие недели цифры выровняются.","Реальный результат обогнал расчёт. Чаще всего это вода — в следующие недели она вернётся на место.","Вышло быстрее, чем я ждала. Обычно тут замешана вода; через пару недель всё выровняется.","Результат пришёл к финишу раньше. Как правило, это вклад воды, и в следующие недели он сравняется с расчётом."],"t_wok":["Ожидаемый и реальный результат почти близнецы — счёт работает как часы.","Мой расчёт и весы показывают почти одно и то же. Записи точные.","План и результат пожали друг другу руки — разницы почти нет.","Цифры сходятся: записанное работает как надо. Отлично.","Между ожидаемым и реальным почти нет разницы — значит, дневник говорит правду."],"t_yog":["Жиры в этом периоде явно солируют — больше 45 %. Давайте 1–2 раза в неделю заменим одно из блюд выше на что-то полегче.","Жиров на тарелке многовато: за 45 %. Одно из верхних блюд может 1–2 раза в неделю уступить место лёгкому соседу.","Я заметила: жиры заняли больше 45 %. Пусть одно блюдо из списка 1–2 раза в неделю отдыхает, а на смену выйдет что-то полегче.","Жиры здесь как дома — больше 45 %. Замена одного из блюд выше на более лёгкое 1–2 раза в неделю их немного потеснит.","Доля жиров перевалила за 45 % — щедро. Можно 1–2 раза в неделю подменять одно из верхних блюд чем-то полегче."],"t_yogOk":["Жиры знают своё место — доля близка к норме. Так и продолжаем.","С жирами у нас договорённость: держатся у нормы и не шумят.","Жиры в этот раз скромничают — почти в норме. Отлично.","Я проверила: жиры за линию нормы не выходят. Тарелка в равновесии.","Жиры на месте, рядом с нормой. В этом разделе можно выдохнуть."],"t_yoz":["Несколько дней в дневнике пустые или наполовину — гадать я не умею. Записывайте основное каждый день, и счёт будет точным.","Некоторые дни прошли молча — без записей или не до конца. Если записывать основное каждый день, цифры скажут правду.","В календаре есть загадочные дни: не записаны или записаны частично. Основные приёмы пищи каждый день — и загадок не останется.","Я пропустила пару дней — их не записали или записали не всё. Записывайте основное каждый день, и счёт сойдётся.","В несколько дней тарелка выглядит пустой — на деле их просто не записали. Основное каждый день сделает анализ точнее."],"t_yozOk":["Дневник почти без пробелов — я вижу каждый день. Отлично.","Дни записаны почти целиком — для анализа это праздник.","Записи такие полные, что цифрам можно верить. Спасибо.","Я проверила: почти ни один день не сбежал. Прекрасно.","Календарь почти заполнен — загадочных дней нет."],"x_nx0":["Завтра в том же ритме — формула работает","Завтра так же: команда в прежнем составе","Завтра на бис: сегодняшний рецепт удался","Завтра той же дорогой — она верная","Завтра как сегодня — я в рядах ваших болельщиков"],"x_nxC":["Завтра хлеба полкуска — остальное в запасе","Завтра у хлеба роль второго плана — полкуска","Завтра договор с хлебом: полкуска","Завтра хлеб скромнее: полкуска на приём","Завтра лепёшка в скромной роли: полкуска"],"x_nxF":["Завтра на обеде главная роль у курицы или рыбы","Завтрашний обед — очередь курицы или рыбы","Завтра приглашаем на обед рыбу или курицу","Завтра лёгкий обед: на сцене курица или рыба","Запишите в меню на завтрашний обед курицу или рыбу"],"x_nxK":["Завтра ужин на тарелке поменьше — глаза тоже обманутся","Завтра вечером тарелка меньше, а вкус тот же","Завтра на ужине дежурит маленькая тарелка","Завтра ужин в компактном формате","Завтра маленькая тарелка сделает большое дело"],"x_nxLow":["Завтра три сытных приёма пищи — начиная с завтрака","Завтра завтрак не пропускаем, а дальше обед и ужин","Завтра порадуйте себя тремя вкусными приёмами пищи","Завтра завтрак, обед и ужин — все трое вас ждут","Завтра начнём день с сытного завтрака"],"x_nxP":["Завтра на завтрак зовём яйцо или катык","Звёзды завтрашнего завтрака — яйцо и катык","Завтра утром вас ждут яйцо или катык","Завтра начинаем утро с яйца или катыка","Завтра на завтрак — белковый десант: яйцо или катык"],"x_off0":["Отклонений нет — день не свернул с дороги","Никто не сбился с пути — всё около цели","Сегодня тарелка и цель подружились","Искала, к чему придраться, — не нашла","Все показатели сидят на своих местах"],"x_offC":["Хлеб сегодня в главной роли: +{x} г углеводов ({src})","Углеводов на {x} г больше — звёзды дня: {src}","Углеводы пришли с запасом в {x} г — {src}","Сладкое и мучное сегодня активны: +{x} г углеводов","Углеводы обогнали план на {x} г"],"x_offF":["Жиры загостились на {x} г — спасибо, {src}","Жиры сегодня щедрые: +{x} г ({src})","Жиры перевыполнили план на {x} г — главные герои: {src}","Масло сегодня разговорилось: +{x} г жиров","Жиров набежало на {x} г больше"],"x_offK":["Калории вышли за линию на {x} ккал — {src}","Сверх нормы {x} ккал — звезда дня: {src}","Калории сегодня прогулялись на {x} ккал дальше","День вышел сытным: +{x} ккал ({src})","Калории перешагнули границу на {x} ккал"],"x_offLow":["Сегодня совсем мало: {k} ккал (безопасная граница {min}). Я за вас переживаю","Всего {k} ккал — это ниже {min}. Берегите себя","{k} ккал — ниже безопасной границы в {min}. Завтра порадуйте себя сытной едой","День вышел слишком лёгким: {k} ккал при границе {min}. Меня это беспокоит","Съедено всего {k} ккал (лучше не меньше {min}). Давайте позаботимся о себе"],"x_offP":["Белок застрял в очереди: не хватило {x} г","Белок сегодня скромничал — недобор {x} г","Белок не дотянул до финиша {x} г","В плане по белку осталось {x} г пустого места","Белка пришло меньше: на {x} г"],"x_okK":["Калории не вышли за линию: {v} / {g} ккал","Калории сегодня дисциплинированы: {v} / {g} ккал","Калории попали в цель: {v} / {g} ккал","{v} / {g} ккал — день прошёл в равновесии","Калории уважили свою границу: {v} / {g} ккал"],"x_okN":["Дневник в порядке — записей: {n}, счёт кристальный","Записей за день: {n} — ни одна тарелка не спряталась","Тарелки на учёте: {n} — счёт точный","Записано приёмов пищи: {n} — я всё вижу","Каждый кусочек на счету — записей: {n}"],"x_okP":["Белок на пятёрку: {v} / {g} г","Белок справился с планом: {v} / {g} г","Белок сегодня герой дня: {v} / {g} г","Белок на финише: {v} / {g} г — браво","{v} / {g} г белка — сытость на вашей стороне"],"x_okS":["Ноги сегодня потрудились — шагов: {v}","Кроссовки довольны — шагов: {v}","Прогулочный счёт дня: {v}","Шагомер сегодня не скучал: {v}","Дорога пройдена — шагов за день: {v}"],"x_okW":["План по воде выполнен: {v} мл","С водой сегодня дружба: {v} мл","Стаканы поработали: {v} мл воды","Цель по воде покорена: {v} мл","{v} мл воды — день прошёл бодро"]},"jiddiy":{"c_noon":["Уже полдень, а за сегодня ещё ничего не записано. Вы завтракали?","Здравствуйте! Сегодня пока нет записей. Всё в порядке?","Прошло полдня. Запишите, что вы ели, — и я продолжу подсчёт.","Что вы сегодня ели? Список пока пуст.","Время обеда. Если утром что-то ели, давайте добавим."],"cel_day":["Норма соблюдена точно: {k} / {l} ккал. От души поздравляю.","Сегодня {k} / {l} ккал — идеальный результат.","Дневная норма выполнена точно: {k} / {l} ккал. Молодец.","День завершился по плану: {k} / {l} ккал. Поздравляю.","Очень хороший день: {k} / {l} ккал, полностью в норме."],"cel_p":["Цель по белку на сегодня выполнена: {p} / {g} г. Очень хорошо.","Вы достигли цели по белку — {p} / {g} г. Поздравляю.","{p} г белка — план на сегодня выполнен.","Белка сегодня достаточно: {p} / {g} г. Молодец.","Искренне рада: {p} г белка, цель выполнена."],"d_empty":["В тот день ничего не записано.","Записей за этот день нет — посчитать не получится.","За тот день данных нет — анализировать нечего.","В этот день приёмы пищи не отмечены.","Тот день пустой — еда не внесена."],"d_low":["В тот день съедено заметно меньше нормы. Возможно, записано не всё.","Калорийность этого дня очень низкая. Регулярное питание важно.","Потребление сильно ниже нормы. Возможно, часть еды не попала в записи.","В тот день калорий было очень мало. Хорошо, если такие дни — редкость.","Этот день заметно ниже нормы. Проверьте, всё ли внесено."],"d_ok":["Тот день прошёл в норме — хороший результат.","Калории в этот день в пределах нормы. Отлично.","День с соблюдённой нормой. Такой режим даёт результат.","Тот день соответствует цели. Хорошая работа.","Этот день был сбалансированным — так и продолжайте."],"d_over":["В тот день калорий было на {x} ккал больше нормы. Один день не меняет общей картины.","Этот день — на {x} ккал выше нормы. Важнее среднее за неделю.","Превышение нормы на {x} ккал. Последующие дни восстановят баланс.","В тот день +{x} ккал. Можно спокойно продолжать.","Калории в этот день выше нормы на {x} ккал — повода для беспокойства нет."],"g_day":["Хорошего дня. Записывайте обед — так подсчёт будет точнее.","Здравствуйте! Середина дня — не забывайте про воду.","Добрый день. Я слежу за сегодняшними записями.","Скоро обед — пусть он будет сытным и сбалансированным.","Как проходит день? Я рядом."],"g_evening":["Добрый вечер. Запишите ужин, и я подготовлю итог дня.","Хорошего вечера. Как прошёл день?","Лёгкий ужин помогает лучше спать.","Давайте вместе завершим этот день.","Наступил вечер. Итоги дня почти готовы."],"g_morning":["Доброе утро. Хорошо начать день со стакана воды и лёгкого завтрака.","Сегодня снова идём вместе — хорошего утра!","Запишите завтрак — и я помогу спланировать день.","С новым днём! Новый день — новые возможности.","Здравствуйте. Я здесь, если появятся вопросы."],"g_night":["Уже поздно. Хороший сон так же важен, как питание, — отдохните.","Спокойной ночи. Завтра продолжим вместе.","Близится полночь. Сон — одна из самых полезных частей дня.","Ещё не спите? Дайте себе отдохнуть, завтра новый день.","Желаю спокойной ночи. Пора завершать день."],"m_eve":["В {n} из последних дней ужин был самым большим приёмом пищи. Лучше сделать обед сытнее.","Основная часть калорий в {n} из последних дней приходилась на вечер. Уделим больше внимания обеду.","Ужин в {n} из последних дней занимал самую большую долю дня. Сытный обед это выровняет.","Предлагаю добавить в обед белок и овощи: в {n} из последних дней вечером ели больше всего.","Плотный приём пищи в середине дня облегчит вечер — ужин преобладал в {n} из последних дней."],"m_fat_better":["Вчера жиров было на {x} г больше цели, сегодня заметно лучше. Молодец.","Сегодня жиры близки к норме. По сравнению со вчера — хороший результат.","После вчерашних лишних {x} г жира сегодня баланс восстановлен.","По жирам сегодня гораздо лучше — вчера было на {x} г больше.","Хорошая перемена: сегодня жиры под контролем. Продолжаем."],"m_kcal_better":["Вчера норма была превышена на {x} ккал, сегодня всё в порядке.","Сегодня норма соблюдена. После вчерашних +{x} ккал это хороший результат.","Баланс восстановлен: вчера было +{x} ккал, сегодня вы в норме.","Сегодняшний подсчёт соответствует плану. Вчера осталось позади.","Хорошее возвращение — сегодня вы в пределах нормы."],"m_prot3":["Уже {n}-й день белок не достигает цели. Сегодня на завтрак хорошо добавить яйцо или катык.","Белка мало {n}-й день подряд. На обед подойдут курица или рыба.","{n}-й день белка не хватает. Утром яйцо, в обед курица — это поможет.","Цель по белку не выполняется уже {n}-й день. Катык и рыба легко это восполнят.","По белку отставание — {n}-й день. Давайте добавим источник белка в каждый приём пищи."],"m_pstreak":["{n}-й день подряд цель по белку выполнена. Прекрасный результат.","Цель по белку выполняется уже {n}-й день. Молодец.","Белка достаточно {n}-й день подряд. Это очень хорошая привычка.","Уже {n}-й день белок в норме. Продолжаем.","Вы удерживаете цель по белку {n}-й день. Поздравляю."],"m_skipbf":["В {n} из последних 5 дней завтрак не записан. Лёгкий завтрак помогает хорошо начать день.","Без завтрака прошло {n} из 5 дней. Яйцо или каша — быстрый и сытный вариант.","Завтрак пропущен в {n} из последних 5 дней. Попробуем завтра начать с катыка?","Утреннего приёма пищи нет в {n} из 5 дней. Даже небольшой завтрак помогает в течение дня.","Предлагаю завтра лёгкий завтрак: в {n} из 5 дней его не было."],"m_streak":["{n}-й день подряд вы в норме. Отличный результат, продолжаем.","Уже {n}-й день в норме — это устойчивая привычка.","Подсчёт совпадает с планом {n}-й день. Молодец.","Вы держите норму {n}-й день подряд. Это большое достижение.","Стабильный результат — {n}-й день. Так держать."],"mk_c_bajarildi":["Углеводы в норме — хорошо.","Цель по углеводам достигнута. Это помогает держать энергию ровной весь день.","Углеводы в пределах цели. Дальше можно сделать упор на белок и овощи.","Дневная цель по углеводам выполнена.","Углеводов достаточно. Такой режим стоит сохранить."],"mk_c_deyarli":["Углеводы близки к цели: ещё {left} г.","Углеводы почти у цели. В оставшихся приёмах хлеб лучше не добавлять.","До цели по углеводам {left} г — хватит одного фрукта.","Углеводы подходят к цели. Дальше лучше без сладкого и лишнего хлеба.","По углеводам осталось {left} г. Эту разницу закроют овощи или фрукт."],"mk_c_kam":["Углеводов пока мало — за день доберутся хлебом, кашей или фруктами.","До цели по углеводам {left} г. Добавьте к следующему приёму кашу или фрукт.","Углеводов пока немного. Хорошие источники — цельнозерновой хлеб и гречка.","Есть место ещё для {left} г углеводов — подойдут фрукты и каши.","Углеводов съедено мало. До конца дня можно сделать упор на крупы и фрукты."],"mk_c_oshdi":["Углеводов на {x} г больше. Полкуска хлеба вместо целого — самый простой шаг.","Углеводы выше цели на {x} г. В следующий приём уменьшите хлеб и сладкое.","Лишние {x} г углеводов. Гарнир хорошо заменить овощами.","Перебор углеводов — {x} г. Даже на полкуска хлеба меньше — уже заметная разница.","Углеводов больше цели на {x} г. Можно сократить сладкие напитки и добавку хлеба."],"mk_f_bajarildi":["Жиры около цели. Жирные блюда на сегодня лучше на этом остановить.","Цель по жирам достигнута. Остальные приёмы пищи выберите понежирнее.","Жиры в норме. Дальше хорошо подойдут овощи, курица или рыба.","Дневная цель по жирам выполнена — дальше лучше без жирных добавок.","Жиров достаточно. До конца дня переходим на более лёгкие блюда."],"mk_f_deyarli":["Жиры близки к цели: ещё {left} г. Добавлять жир отдельно не нужно.","Жиры почти у цели. Остальные приёмы пищи лучше выбрать понежирнее.","До цели по жирам {left} г — обычная еда закроет это сама.","Жиры подходят к цели. Масло и сметану сегодня лучше не добавлять.","До цели по жирам не хватает {left} г. Остальное придёт с едой, отдельно добавлять не стоит."],"mk_f_kam":["Жиров пока мало — это хорошо. За день они доберутся с обычной едой.","До цели по жирам {left} г. Добавлять что-то специально не нужно.","Жиров пока немного. Остальное наберётся с оставшимися приёмами пищи.","Запас по жирам — {left} г. Это нормально, отдельно жир добавлять не стоит.","Потребление жиров невысокое. Обычные блюда восполнят его к концу дня."],"mk_f_oshdi":["Жиров на {x} г больше цели. В следующий приём выберите понежирнее: курица, рыба, овощи.","Жиры превышены на {x} г. Дальше подойдёт отварная курица или рыба вместо жареного.","Лишние {x} г жиров. Уравновесьте следующий приём овощами и нежирным белком.","Жиры выше нормы на {x} г — к следующему приёму хорошо подойдёт рыба или куриная грудка.","По жирам перебор на {x} г. В оставшихся блюдах можно уменьшить масло и сметану."],"mk_p_bajarildi":["Цель по белку выполнена: {v}/{g} г. Сытость сохранится дольше.","Белка достаточно — {v}/{g} г. Это помогает держать аппетит ровным.","Цель по белку достигнута. Чувство сытости продержится до следующего приёма пищи.","{v}/{g} г белка — цель выполнена. Хорошо бы сохранить такой режим.","Белок в норме. В такие дни реже тянет перекусить лишнего."],"mk_p_deyarli":["Почти: до цели по белку ещё {left} г. Хватит одного яйца или стакана катыка.","Белка не хватает совсем немного — {left} г. Можно добрать творогом или сыром.","До цели по белку {left} г. Добавьте к ужину кусочек курицы или рыбы.","Осталось {left} г белка — стакан катыка закроет эту разницу.","Белок близок к цели: не хватает {left} г. Яйцо или йогурт — хороший вариант."],"mk_p_kam":["Белка пока мало: ещё {left} г. Хорошие источники — яйца, катык, курица, рыба.","До цели по белку не хватает {left} г — добавьте в следующий приём курицу, рыбу или бобовые.","Осталось {left} г белка. Удобнее всего добрать яйцом, творогом, катыком или фасолью.","Белка меньше цели на {left} г. Давайте в следующий раз выберем рыбу или курицу.","Чтобы добрать белок, осталось {left} г — стакан катыка и яйцо будут хорошим началом."],"mk_p_oshdi":["Белка на {x} г больше цели. Обычно это не проблема, но следите за общей калорийностью.","Белка больше, чем нужно. Вреда мало, просто учитывайте лимит калорий.","Белок выше цели на {x} г — как правило, это безопасно. Важно, чтобы калории остались в норме.","Белка много. Для сытости это хорошо, но калории лучше держать в пределах нормы.","На {x} г белка больше цели — повода для тревоги нет. Просто следите за балансом калорий."],"q_full":["Чувствуете ли вы сытость после сегодняшней еды?","Как сейчас ощущается сытость?","Хватило ли вам сегодняшней еды?","Вы сыты или хочется ещё чего-нибудь?","Короткий вопрос: сейчас вы сыты?"],"q_mood":["Какое у вас сегодня настроение?","Как идёт ваш сегодняшний день?","Что скажете о самочувствии сегодня?","Складывается ли сегодня день так, как хотелось?","Короткий вопрос: как настроение?"],"qr_full_mid":["Ясно. В пределах {left} ккал можно лёгкий перекус — катык или фрукт.","Небольшой перекус, если хочется: пиала катыка или яблоко.","Есть {left} ккал. Фрукт или катык — лёгкий и сытный вариант.","Подойдут катык или груша, если хочется что-то добавить.","Если чувство среднее, можно взять что-то лёгкое — в пределах {left} ккал."],"qr_full_no":["Понятно. У вас есть {left} ккал — яйцо или катык будут хорошим выбором.","Осталось {left} ккал. Белковый перекус — творог или курица — надолго насытит.","Можно поесть ещё: {left} ккал. Предлагаю варёное яйцо или катык.","Запас — {left} ккал. Курица или творог сытные и лёгкие.","Давайте возьмём что-то белковое в пределах {left} ккал: яйцо, катык или творог."],"qr_full_yes":["Хорошо. Если вы сыты, есть через силу не нужно — это верное решение.","Замечать сытость — очень важный навык.","Понятно. Прислушиваться к своим ощущениям — лучший путь.","Замечательно. Умение вовремя остановиться — основа здорового питания.","До следующего приёма пищи можно спокойно подождать."],"qr_mood_bad":["Мне жаль. Сегодня мои советы будут мягче. Позаботьтесь о себе.","Сочувствую. Сегодня цифры не главное — главное вы.","Такие дни случаются. Сегодня никакого давления, я буду мягче.","Спасибо, что сказали. Советы сегодня будут лёгкими, постарайтесь отдохнуть.","Я рядом. Сегодня не думайте о еде, советы будут мягкими."],"qr_mood_good":["Рада это слышать. Хорошего вам продолжения дня.","Замечательно! Хорошее настроение — хороший день.","Очень хорошо. Пусть таких дней будет больше.","Мне приятно. Я рада за вас.","Продолжаем в том же духе."],"qr_mood_ok":["Понимаю. Обычные дни тоже бывают, я рядом.","Спасибо, что поделились. Будьте сегодня к себе внимательнее.","Дни бывают разными. К вечеру всё может наладиться.","Ясно. Небольшая прогулка или чай могут поднять настроение.","Хорошо. Я здесь — поговорим, когда захотите."],"r_a":["Жиры сегодня выше цели на {x} г, в основном это {src}. Для следующего приёма пищи хороши курица, рыба или овощи.","Превышение по жирам — {x} г. Основной источник: {src}. Следующий приём пищи лучше сделать с нежирным белком.","Жиров на {x} г больше нормы. Вместо жареного в следующий раз подойдёт отварная курица или рыба на пару.","Сейчас жиры выше цели на {x} г. Лёгкий ужин из рыбы или курицы с овощами выровняет день.","На {x} г жиров больше, чем нужно, — это легко поправить. В следующий приём пищи подойдут нежирное мясо, рыба и овощи."],"r_b":["Углеводов на {x} г больше цели, белка не хватает {p} г. В следующий приём пищи уменьшите хлеб и добавьте яйца или катык.","Сегодня углеводы +{x} г, белок отстаёт на {p} г. Курица, яйца или катык выровняют оба показателя.","Основная часть углеводов — {src}, превышение {x} г. До цели по белку {p} г: хороший выбор — яйца или курица.","Углеводы выше нормы на {x} г, белка меньше на {p} г. Советую заменить часть хлеба курицей или катыком.","Пока углеводов +{x} г, а белка не хватает {p} г. Если заменить часть хлеба яйцом или катыком, сытость продержится дольше."],"r_c":["Сегодня не хватает {p} г белка. Добавьте на ужин курицу, рыбу или катык — и цель достигнута.","До цели по белку осталось {p} г. Ужин — самое удобное время: подойдут яйца или рыба.","Вечером белку ещё недостаёт {p} г. Порция курицы или рыбы поможет закрыть разницу.","Чтобы выйти на цель по белку, нужно ещё {p} г. Сделайте основой ужина мясо, яйца или катык.","Пока белка меньше цели на {p} г. Белковый ужин поможет дольше оставаться сытым до утра."],"r_d":["Калории в норме, но {sh} % из них — жиры, в основном {src}. С большим количеством белка вы дольше сыты.","Сегодня {sh} % калорий пришло из жиров. Если в следующий приём пищи выбрать нежирный белок, соотношение выровняется.","Общая калорийность верная, но доля жиров — {sh} %. Завтра добавьте больше курицы, рыбы или яиц: сытость сохранится дольше.","Жиры составили {sh} % калорий. Больше белка и овощей сделают день сбалансированнее.","Калории на месте, но состав сместился к жирам — {sh} %. В следующий приём пищи сделайте акцент на белке."],"r_e":["Сегодня на {x} ккал больше нормы — это один день, волноваться не о чем. Завтра достаточно чуть меньшей порции на ужин.","Норма превышена на {x} ккал, основной источник — {src}. Один день не портит результат; завтра попробуйте меньше хлеба.","{x} ккал сверх нормы — обычная ситуация. Небольшой шаг на завтра: 15 минут пешком.","Сегодня норма выше на {x} ккал. Важна недельная картина; завтра сделайте один приём пищи богаче овощами.","Превышение — {x} ккал, но это всего один день. Завтра можно заменить сладкий напиток водой или чаем."],"r_f":["Сегодня калории, белки, жиры и углеводы — в норме. Очень хороший результат.","Сбалансированный день: все показатели около цели. Продолжим так же завтра.","Калории и макросы соответствуют цели. Такие дни закрепляют результат — искренне рада.","День выстроен правильно: достаточно белка, жиры и углеводы в норме. Вы отлично справились.","Все показатели на месте. Ваш выбор сегодня был точным и продуманным — так держать."],"r_kam":["Сегодня пока {k} ккал — это ниже безопасной границы ({min} ккал). Слишком мало еды вредно для здоровья; добавьте ещё один сытный приём пищи.","За сегодня {k} ккал, а нижняя безопасная граница — {min} ккал. Прошу вас сделать ужин полноценным и сытным.","{k} ккал — меньше безопасного минимума ({min} ккал). Организму нужна энергия, пожалуйста, добавьте ещё одну полноценную еду.","Внимание: сегодня всего {k} ккал, это ниже {min} ккал. Завершите день сытной едой с белком и углеводами.","Пока записано {k} ккал — меньше {min} ккал. Такое малое количество вызывает усталость; рекомендую добавить ещё один приём пищи."],"re_fat":["В блюде {name} {fg} г жира. Следующий приём пищи лучше сделать полегче.","{name} — довольно жирное блюдо: {fg} г. К следующему приёму подойдут овощи или катык.","Жиры: {name} — {fg} г. Более лёгкие блюда в течение дня помогут сохранить баланс.","Это не проблема: +{fg} г жира ({name}), достаточно, чтобы следующий приём был легче.","Для следующего приёма советую что-то тушёное или отварное — в блюде {name} {fg} г жира."],"re_first":["Первый приём пищи: {name}, {k} ккал. На сегодня осталось {left} ккал.","Хорошее начало. {name} — {k} ккал; дневной запас {left} ккал.","В дневнике: {name}, {k} ккал. Это первая запись за день.","Первое блюдо добавлено: {name} ({k} ккал). Продолжаем.","Счёт дня открыт: {name}, {k} ккал. Остаётся {left} ккал."],"re_goal":["С блюдом {name} вы почти достигли нормы — осталось {left} ккал.","Вы в хорошей точке: {name} учтено, до нормы {left} ккал.","Дневная норма почти выполнена. После блюда {name} осталось {left} ккал.","Есть: {name}. Осталось {left} ккал — день хорошо завершается.","Остаток до нормы — {left} ккал, с учётом блюда {name}. Вы близко."],"re_light":["{name} — всего {k} ккал. Лёгкий и полезный выбор.","Очень хорошо: {name}, {k} ккал. Такие блюда держат день в балансе.","Мало калорий и много пользы: {name}, {k} ккал. Молодец.","Добавлено лёгкое блюдо: {name}, {k} ккал. Правильный выбор.","Удачное дополнение к рациону — {name}, {k} ккал. Так держать."],"re_ok":["Добавлено: {name}, {k} ккал. Вы в пределах нормы, осталось {left} ккал.","Записала — {name}, {k} ккал. На день остаётся {left} ккал.","{name} ({k} ккал) хорошо вписывается в норму. Запас: {left} ккал.","Всё по плану: {name}, {k} ккал. Остаток — {left} ккал.","{name}, {k} ккал — в рамках нормы. Впереди {left} ккал."],"re_over":["С блюдом {name} норма превышена на {x} ккал. Один день ничего не портит — завтра продолжим.","Сегодня +{x} ккал к норме ({name}). Не волнуйтесь, важнее общее направление.","После блюда {name} норма превышена на {x} ккал. Такие дни бывают, завтра — как обычно.","Норма превышена на {x} ккал — {name}. Повода для тревоги нет, недельный итог важнее.","Сверх нормы {x} ккал ({name}). Ничего не потеряно, завтра идём по плану."],"re_pgoal":["Вместе с блюдом {name} цель по белку на сегодня выполнена: {p} г. Отличный результат.","Цель по белку достигнута — {p} г. Последним шагом стало блюдо {name}. Поздравляю.","Сегодня {p} г белка — цель выполнена. Завершающее блюдо: {name}.","Искренне рада: с блюдом {name} белок дошёл до {p} г.","Белок за день — {p} г с учётом блюда {name}. Цель выполнена."],"re_prot":["{name}: {pg} г белка. До дневной цели осталось {pleft} г.","Хороший источник белка: {name}, {pg} г. До цели {pleft} г.","Оставшиеся {pleft} г доберём позже — сейчас {name}, {pg} г белка.","Шаг к цели: +{pg} г белка ({name}), осталось {pleft} г.","Богато белком: {name}, {pg} г. До сегодняшней цели {pleft} г."],"rt_a":["Жиры выше цели на {x} г","Жиров на {x} г больше","Превышение жиров: {x} г","Жиры: +{x} г к цели","Жиры сегодня выше нормы"],"rt_b":["Углеводов больше, белка мало","Углеводы выше цели на {x} г","Белок отстаёт от углеводов","Перекос в сторону углеводов","Углеводы: +{x} г"],"rt_c":["Белка ещё {p} г","До цели по белку {p} г","Осталось {p} г белка","Белок: не хватает {p} г","Нужно ещё {p} г белка"],"rt_d":["Доля жиров: {sh} %","Состав перекошен","Калории в норме, жиров много","{sh} % калорий — из жиров","Многовато жиров в составе"],"rt_e":["Выше нормы на {x} ккал","Сегодня +{x} ккал","Норма превышена на {x} ккал","Немного больше нормы","Сверх нормы: {x} ккал"],"rt_f":["Сбалансированный день","Все показатели в норме","День точно по плану","Отличный баланс","Калории и макросы в норме"],"rt_kam":["Вы едите слишком мало","Сегодня всего {k} ккал","Ниже безопасной границы","Еды недостаточно","Добавьте ещё приём пищи"],"s_day1":["Это ваш первый день. Записывайте еду — советы начнутся завтра.","Чтобы советовать точно, мне нужно узнать ваши привычки. Сегодня просто записывайте, анализ — с завтрашнего дня.","В первый день я не даю советов — сначала собираем данные. Персональные рекомендации появятся завтра.","Сегодня просто записывайте. Завтра я дам первый совет на основе ваших данных.","День знакомства: сегодняшние записи станут основой будущих советов. Советы — с завтрашнего дня."],"s_ok":["Пока всё в порядке: сегодня {k} / {l} ккал, остаётся {left} ккал.","Сегодня {k} / {l} ккал. Вы в пределах нормы, осталось {left} ккал.","Показатели хорошие: {k} / {l} ккал. До конца дня есть {left} ккал.","{k} / {l} ккал — идёте по плану. Запас: {left} ккал.","Всё по плану: употреблено {k} / {l} ккал, ещё доступно {left} ккал."],"s_wait":["Сегодня записано пока мало. Осталось записей до совета: {n}.","Для точного совета добавьте ещё что-нибудь ({n} из 2).","Картина дня пока неполная. Записей до анализа: {n}.","Когда записей станет больше (осталось: {n}), я дам рекомендацию по составу дня.","Данных пока мало. Добавьте записи — осталось {n}, и я подведу итог дня."],"t_dam":["В выходные калорий больше. На субботу и воскресенье достаточно одного простого правила, например сладкое один раз.","Суббота и воскресенье заметно выше будней. Задайте одно правило: скажем, сладкое один раз в день.","Разница в основном в выходные. Одно понятное правило на конец недели, например сладкое один раз, хорошо работает.","Я вижу, что в выходные вы едите больше. Простое правило — сладкое один раз — сократит эту разницу.","К концу недели калории растут. Выберите одно правило на субботу и воскресенье, например сладкое только один раз."],"t_damOk":["Разница будней и выходных небольшая — хорошо.","Выходные почти не отличаются от будней. Стабильный режим.","В субботу и воскресенье калорий примерно как в будни — это очень хорошо.","Я не вижу большой разницы между буднями и выходными. Сохраняйте этот режим.","Питание ровное всю неделю, включая выходные."],"t_ich":["Напитки дают заметные калории. Хороший выбор — заменить сладкие напитки водой или чаем без сахара.","Часть калорий приходится на напитки. Попробуйте вместо сладких пить воду или чай без сахара.","Калорий из напитков много. Самая простая перемена — вода или чай без сахара вместо сладкого.","Я вижу заметный вклад напитков. Замена сладких на воду или чай без сахара быстро даст разницу.","Сладкие напитки заметно добавляют к дневному счёту. Если заменить их водой или чаем без сахара, будет лучше."],"t_ichOk":["Калорий из напитков мало.","Напитки почти не влияют на дневной счёт — хорошо.","В напитках мало калорий. Здесь всё в порядке.","Я вижу, что калорий из напитков немного. Сохраняйте эту привычку.","С напитками порядок: калорий от них мало."],"t_kechki":["Больше 40 % дня приходится на ужин. Если обед сделать сытнее, вечером будет проще.","Доля ужина выше 40 %. Сытный обед естественно снижает аппетит вечером.","Большая часть калорий — больше 40 % — приходится на вечер. Белок и овощи в обед сделают ужин легче.","Я вижу, что больше 40 % дня — на ужин. Самое простое решение — чуть более сытный обед.","Вечером съедается больше 40 % дневных калорий. Если обед будет сытнее, ужин пройдёт легче."],"t_kechkiOk":["Доля ужина в норме.","Калории распределены по дню правильно, ужин не перегружен.","Ужин не выходит за норму в дневном счёте — хороший режим.","Я вижу, что доля ужина в норме. Сохраняйте такое распределение.","Вечером съедается умеренно — здесь всё в порядке."],"t_noMain":["Больших отклонений нет — режим хороший.","Серьёзных отклонений в этом периоде нет. Питание стабильное.","Я не вижу крупных отклонений. Сохраняйте текущий режим.","Анализ не показал больших проблем — хороший результат.","Показатели около нормы, крупных отклонений нет."],"t_oqsil":["Цель по белку выполнялась редко. Добавить к завтраку яйцо или катык — самый простой путь.","Белка не хватало в большинстве дней. Яйцо или катык утром быстро закроют эту разницу.","Цели по белку удавалось достичь нечасто. Удобно начать с завтрака: яйцо или катык.","Я вижу, что цель по белку часто не выполнялась. Попробуйте добавлять к завтраку яйцо или катык.","Дней с достаточным белком мало. Самый простой шаг — яйцо или катык на завтрак каждый день."],"t_oqsilOk":["Цель по белку выполнялась в большинстве дней.","Дней с достаточным белком — большинство. Хороший результат.","В большинстве дней цель по белку достигнута. Сохраняйте эту привычку.","Я вижу стабильный результат по белку: цель выполнена в большинстве дней.","С белком порядок — цель выполнена почти во все дни."],"t_top":["Больше всего калорий дало блюдо {f}. Немного уменьшить порцию — самый быстрый шаг.","{f} — самая большая доля. Если брать порцию чуть меньше, разница будет заметна быстро.","Главный источник калорий — {f}. Отказываться не нужно: достаточно чуть меньшей порции.","На первом месте {f}. Чуть меньше на тарелке каждый раз — простой и быстрый путь.","Самый крупный вклад даёт {f}. Небольшое уменьшение порции сработает быстрее других изменений."],"t_wless":["Реальный результат медленнее ожидаемого. Чаще всего причина — вода и соль (колебания 1–2 кг между днями) или незаписанная еда.","Результат отстаёт от расчёта. Обычно это вода и соль — показания меняются на 1–2 кг от дня ко дню — или пропущенные записи.","Я вижу, что реальный результат медленнее ожидаемого. Вода и соль дают разницу 1–2 кг; проверьте и незаписанные приёмы пищи.","Между ожидаемым и реальным есть разница. Частые причины: вода и соль (колебания 1–2 кг) или незаписанная еда.","Реальный результат медленнее. Часто это временно: вода и соль меняют показания на 1–2 кг. Причиной может быть и незаписанная еда."],"t_wmore":["Реальный результат быстрее ожидаемого — чаще всего за счёт воды; в следующие недели выровняется.","Результат опережает расчёт. Обычно это связано с водой и в ближайшие недели стабилизируется.","Я вижу, что реальный результат быстрее ожидаемого. Часто это потеря воды, со временем всё выровняется.","Изменение быстрее ожидаемого чаще всего связано с водой. В следующие недели цифры приблизятся к расчёту.","Реальный результат быстрее. Обычно это временно: дело в воде, и в следующие недели всё выровняется."],"t_wok":["Ожидаемый и реальный результат почти совпадают — расчёт работает верно.","Расчёт по записям соответствует реальному результату.","Я не вижу большой разницы между ожидаемым и реальным. Записи точные.","Результат близок к расчёту — значит, еда записывается правильно.","Ожидаемая и реальная динамика совпадают. Продолжайте в том же порядке."],"t_yog":["Доля жиров выше 45 %. Хорошее начало — 1–2 раза в неделю заменять одно из блюд выше на более лёгкое.","Больше 45 % калорий приходится на жиры. Попробуйте 1–2 раза в неделю брать вместо одного из верхних блюд более лёгкий вариант.","Я вижу, что жиров больше 45 %. Достаточно 1–2 раза в неделю заменить одно блюдо из списка на более лёгкое.","Жиров больше нормы: свыше 45 %. Самый простой шаг — 1–2 раза в неделю выбирать вместо одного из верхних блюд что-то легче.","Доля жиров вышла за 45 %. Если 1–2 раза в неделю менять одно блюдо из списка на более лёгкое, разница будет заметна."],"t_yogOk":["Доля жиров близка к норме. Здесь можно ничего не менять.","Жиров примерно столько, сколько нужно, — хороший баланс.","Жиры занимают правильную долю в рационе.","Я вижу, что доля жиров близка к норме. Сохраняйте этот порядок.","С жирами всё в порядке: доля не уходит далеко от нормы."],"t_yoz":["Несколько дней не записаны или записаны частично. Для точного счёта записывайте каждый день хотя бы основные приёмы пищи.","В некоторых днях записей нет или они неполные. Если записывать основное каждый день, анализ станет надёжнее.","Есть пропущенные и неполные дни. Записывайте основные приёмы пищи ежедневно — тогда цифры будут верными.","Я вижу несколько неполных дней. Ежедневная запись основных приёмов пищи сделает счёт точнее.","Несколько дней записаны не полностью. Пара секунд в день на основные приёмы пищи заметно повышает точность анализа."],"t_yozOk":["Дни записаны почти полностью.","Записи почти полные — анализ надёжный.","Почти каждый день записан, поэтому цифры точные.","Я вижу почти полные дни. Сохраняйте эту привычку.","Записи ведутся хорошо: пустых дней почти нет."],"x_nx0":["Завтра продолжайте так же","Завтра сохраните сегодняшний режим","Завтра питайтесь так же сбалансированно","Завтра продолжаем те же привычки","Завтра — так же, как сегодня"],"x_nxC":["Завтра хлеба — полкуска","Завтра сократите хлеб до полкуска","Завтра хорошо бы уменьшить хлеб вдвое","Завтра на каждый приём достаточно полкуска хлеба","Завтра поменьше хлеба: полкуска"],"x_nxF":["Завтра на обед выберите курицу или рыбу","Завтра на обед — нежирный белок: курица или рыба","Для завтрашнего обеда хорошо подойдут курица или рыба","Завтра спланируйте обед с курицей или рыбой","Завтра на обед — не жареное, а курица или рыба"],"x_nxK":["Завтра ужин — на тарелке поменьше","Завтра немного уменьшите вечернюю порцию","Завтра ужин полегче и поменьше","Завтра вечером возьмите тарелку поменьше","Завтра ужин лучше сделать скромнее"],"x_nxLow":["Завтра три сытных приёма пищи — не пропускайте завтрак","Завтра нормально позавтракайте, пообедайте и поужинайте","Завтра давайте питаться регулярно, три раза в день","Завтра с утра и весь день — еда по норме","Завтра постарайтесь не пропускать приёмы пищи"],"x_nxP":["Завтра на завтрак добавьте яйцо или катык","Завтра в завтрак — белок: яйцо или катык","Для завтрашнего завтрака хорошо подойдут яйцо или катык","Завтра начните завтрак с яйца или творога","Завтра на завтрак — белковое блюдо: яйцо, катык или творог"],"x_off0":["Отклонений нет — всё около цели","Все показатели в норме","Заметных отклонений не было","Отступлений от цели нет","День прошёл по плану"],"x_offC":["Углеводов на {x} г больше — {src}","Углеводы выше цели на {x} г: в основном {src}","По углеводам +{x} г — источник: {src}","Лишние {x} г углеводов","Углеводы превысили норму на {x} г"],"x_offF":["Жиров на {x} г больше — {src}","Жиры выше цели на {x} г: в основном {src}","По жирам +{x} г — источник: {src}","Лишние {x} г жиров","Жиры превысили норму на {x} г"],"x_offK":["Больше нормы на {x} ккал — {src}","Калории выше нормы на {x} ккал: в основном {src}","+{x} ккал к норме — источник: {src}","Лишние {x} ккал","Превышение дневной нормы: {x} ккал"],"x_offLow":["Вы съели слишком мало: {k} ккал (безопасная граница {min})","{k} ккал — ниже безопасной границы ({min})","Потребление очень низкое: {k} ккал, минимум {min} ккал","Сегодня {k} ккал — меньше безопасных {min} ккал","Калорий слишком мало: {k} (безопасная граница — {min})"],"x_offP":["Белка не хватило {x} г","Белок ниже цели на {x} г","Недобор белка: {x} г","По белку дефицит {x} г","До цели по белку не хватило {x} г"],"x_okK":["Калории в норме: {v} / {g} ккал","Дневные калории в пределах: {v} / {g} ккал","{v} / {g} ккал — норма соблюдена","Калории в рамках цели: {v} / {g} ккал","Норма по калориям соблюдена: {v} / {g} ккал"],"x_okN":["Записей за день: {n} — счёт точный","Сегодня записано приёмов пищи: {n}","Записи: {n} — данные полностью учтены","Внесено приёмов пищи: {n}, данные надёжные","Записей за весь день: {n} — анализ точный"],"x_okP":["Цель по белку выполнена: {v} / {g} г","Белка достаточно: {v} / {g} г","По белку цель достигнута: {v} / {g} г","{v} / {g} г белка — цель выполнена","Белок в норме: {v} г при цели {g} г"],"x_okS":["Шаги: {v}","Шагов за сегодня: {v}","Пройдено шагов: {v}","Активность — шагов: {v}","Шаги за день: {v}"],"x_okW":["Цель по воде выполнена: {v} мл","Воды выпито достаточно: {v} мл","{v} мл воды — дневная цель выполнена","Вода в норме: {v} мл","Вода за день: {v} мл — цель достигнута"]}}}; });
